fn sum_evens(xs: [Int]) -> Int {
    let mut total = 0
    for x in xs {
        if x % 2 == 0 {
            total = total + x
        }
    }
    return total
}

fn reverse_words(text: String) -> String {
    let words = text.split(" ");
    let mut result = "";
    let mut i = words.len();
    while i > 0 {
        i = i - 1;
        if result.len() > 0 {
            result = result + " ";
        }
        result = result + words[i];
    }
    return result;
}

fn is_palindrome(text: String) -> Bool {
    let lower = text.to_lower()
    let n = lower.len()
    let mut i = 0
    while i < n / 2 {
        if lower.char_at(i) != lower.char_at(n - 1 - i) {
            return false
        }
        i = i + 1
    }
    return true
}

fn count_vowels(text: String) -> Int {
    let mut count: Int = 0
    for c in text.chars() {
        let lower = c.to_lower()
        if lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u' {
            count = count + 1
        }
    }
    return count
}

fn fizzbuzz(n: Int) -> String {
    if n % 15 == 0 {
        "FizzBuzz"
    } else if n % 3 == 0 {
        "Fizz"
    } else if n % 5 == 0 {
        "Buzz"
    } else {
        n.to_string()
    }
}

fn largest(xs: [Int]) -> Int? {
    if xs.is_empty() {
        return none
    }
    var best = xs[0]
    for x in xs {
        if x > best {
            best = x
        }
    }
    return best
}

fn word_counts(text: String) -> [String: Int] {
    let counts: [String: Int] = {}
    for word in text.split(" ") {
        if counts.contains_key(word) {
            counts[word] = counts[word] + 1
        } else {
            counts[word] = 1
        }
    }
    return counts
}

fn doubled(text: String) -> Int ! BadInput {
    match text.trim().parse_int() {
        Ok(n) => n * 2,
        Err(_) => fail NotANumber(text),
    }
}

fn factorial(n: Int) -> Int {
    let mut result = 1
    let mut i = 2
    while i <= n {
        result = result * i
        i = i + 1
    }
    return result
}

fn fib(n: Int) -> Int {
    let mut a = 0
    let mut b = 1
    let mut i = 0
    while i < n {
        let t = a + b
        a = b
        b = t
        i = i + 1
    }
    return a
}

fn by_length(words: [String]) -> [String] {
    return words.sort_by_key(|w| w.len())
}

fn dedupe(xs: [Int]) -> [Int] {
    let mut result: [Int] = []
    for x in xs {
        let mut seen = false
        for r in result {
            if r == x {
                seen = true
            }
        }
        if !seen {
            result.push(x)
        }
    }
    return result
}

fn total_area(rects: [Rect]) -> Float {
    let mut total = 0.0
    for r in rects {
        total = total + r.width * r.height
    }
    return total
}

fn area(s: Shape) -> Float {
    match s {
        Circle(radius) => 3.14 * radius * radius,
        Square(side) => side * side,
    }
}

fn first_negative(xs: [Int]) -> Int? {
    for i in 0..len(xs) {
        if xs[i] < 0 {
            return i
        }
    }
    return none
}

fn caesar(text: String, k: Int) -> String {
    let mut result = ""
    for c in text {
        let code = c.code()
        if code >= 97 && code <= 122 {
            let shifted = (code - 97 + k) % 26 + 97
            result = result + Char.from_code(shifted).to_string()
        } else {
            result = result + c.to_string()
        }
    }
    return result
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let rows = len(m)
    let cols = len(m[0])
    let result = []
    for j in range(0, cols) {
        let row = []
        for i in range(0, rows) {
            row = push(row, m[i][j])
        }
        result = push(result, row)
    }
    return result
}

fn find(xs: [Int], target: Int) -> Int? {
    let mut lo = 0
    let mut hi = len(xs) - 1
    while lo <= hi {
        let mid = lo + (hi - lo) / 2
        if xs[mid] == target {
            return mid
        } else if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    return none
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail DivideByZero
    }
    return a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let mut groups: [String: [String]] = {}
    for word in words {
        let key = word.first_char().to_string()
        if groups.contains_key(key) {
            groups[key].push(word)
        } else {
            groups[key] = [word]
        }
    }
    return groups
}

fn gcd(a: Int, b: Int) -> Int {
    if b == 0 {
        return a
    }
    return gcd(b, a % b)
}

fn title(text: String) -> String {
    text.split(' ')
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase(),
                None => String::new(),
            }
        })
        .collect::<Vec<String>>()
        .join(" ")
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        return false
    }
    let mut i = 2
    while i * i <= n {
        if n % i == 0 {
            return false
        }
        i = i + 1
    }
    return true
}

fn primes_below(n: Int) -> [Int] {
    let mut result: [Int] = []
    let mut i = 2
    while i < n {
        let mut is_prime = true
        let mut d = 2
        while d * d <= i {
            if i % d == 0 {
                is_prime = false
                break
            }
            d += 1
        }
        if is_prime {
            result.push(i)
        }
        i += 1
    }
    return result
}

fn digit_sum(n: Int) -> Int {
    let mut m: Int = n;
    let mut total: Int = 0;
    while m > 0 {
        total = total + m % 10;
        m = m / 10;
    }
    return total;
}

fn rle(text: String) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let mut count = 1;
        while i + count < chars.len() && chars[i + count] == c {
            count += 1;
        }
        out.push(c);
        out.push_str(&count.to_string());
        i += count;
    }
    out
}

fn balanced(text: String) -> Bool {
    let mut stack = Vec::new()
    for c in text.chars() {
        if c == '(' || c == '[' || c == '{' {
            stack.push(c)
        } else if c == ')' || c == ']' || c == '}' {
            if stack.is_empty() {
                return false
            }
            let open = stack.pop()
            let matched = (open == '(' && c == ')') || (open == '[' && c == ']') || (open == '{' && c == '}')
            if !matched {
                return false
            }
        }
    }
    return stack.is_empty()
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let n = len(xs)
    for i in 0..n {
        for j in (i + 1)..n {
            if xs[i] + xs[j] == target {
                return (i, j)
            }
        }
    }
    return none
}

fn anagrams(a: String, b: String) -> Bool {
    let x = a.to_lower()
    let y = b.to_lower()
    if x.len() != y.len() {
        return false
    }
    let counts: [Int] = [0; 256]
    for c in x.chars() {
        counts[c.code()] += 1
    }
    for c in y.chars() {
        counts[c.code()] -= 1
        if counts[c.code()] < 0 {
            return false
        }
    }
    return true
}

fn roman(n: Int) -> String {
    let values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    let symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    let mut result = ""
    let mut remaining = n
    let mut i = 0
    while remaining > 0 {
        while remaining >= values[i] {
            result = result + symbols[i]
            remaining = remaining - values[i]
        }
        i = i + 1
    }
    return result
}

fn flatten(xss: [[Int]]) -> [Int] {
    let mut result: [Int] = [];
    for xs in xss {
        for x in xs {
            result.push(x);
        }
    }
    return result;
}

fn chunks(xs: [Int], n: Int) -> [[Int]] {
    let mut result: [[Int]] = []
    let len = xs.len()
    let mut i = 0
    while i < len {
        let mut end = i + n
        if end > len {
            end = len
        }
        result.push(xs.slice(i, end))
        i = i + n
    }
    return result
}

fn rotate(xs: [Int], k: Int) -> [Int] {
    let n = len(xs)
    if n == 0 {
        return xs
    }
    let r = k % n
    let mut out: [Int] = []
    for i in 0..n {
        out = push(out, xs[(i + r) % n])
    }
    return out
}

fn common_prefix(words: [String]) -> String {
    if words.len() == 0 {
        return "";
    }
    let mut prefix = words[0].clone();
    for word in words {
        while !word.starts_with(prefix) {
            prefix = prefix.substring(0, prefix.len() - 1);
        }
    }
    return prefix;
}

fn second_largest(xs: [Int]) -> Int? {
    let mut has_first = false
    let mut has_second = false
    let mut largest = 0
    let mut second = 0
    for x in xs {
        if has_first && x == largest {
            continue
        }
        if !has_first || x > largest {
            if has_first {
                second = largest
                has_second = true
            }
            largest = x
            has_first = true
        } else if !has_second || x > second {
            second = x
            has_second = true
        }
    }
    if has_second {
        return second
    }
    return none
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let mut result: [Int] = []
    let mut i = 0
    let mut j = 0
    while i < len(a) && j < len(b) {
        if a[i] <= b[j] {
            result = push(result, a[i])
            i = i + 1
        } else {
            result = push(result, b[j])
            j = j + 1
        }
    }
    while i < len(a) {
        result = push(result, a[i])
        i = i + 1
    }
    while j < len(b) {
        result = push(result, b[j])
        j = j + 1
    }
    return result
}

fn distance(a: String, b: String) -> Int {
    let n = a.len()
    let m = b.len()

    let mut prev: Vec<Int> = Vec::new()
    for j in 0..=m {
        prev.push(j)
    }

    for i in 1..=n {
        let mut curr: Vec<Int> = Vec::new()
        curr.push(i)
        for j in 1..=m {
            let cost = if a.char_at(i - 1) == b.char_at(j - 1) { 0 } else { 1 }
            let del = prev[j] + 1
            let ins = curr[j - 1] + 1
            let sub = prev[j - 1] + cost
            let mut best = del
            if ins < best {
                best = ins
            }
            if sub < best {
                best = sub
            }
            curr.push(best)
        }
        prev = curr
    }

    return prev[m]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        return Stack { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        let n = self.items.len()
        if n == 0 {
            return self
        }
        return Stack { items: self.items.slice(0, n - 1) }
    }

    fn top(self) -> Int? {
        let n = self.items.len()
        if n == 0 {
            return none
        }
        return self.items[n - 1]
    }
}

fn count_char(text: String, c: Char) -> Int {
    let mut count = 0
    for ch in text {
        if ch == c {
            count = count + 1
        }
    }
    return count
}

fn median(xs: [Float]) -> Float {
    let mut v = xs.clone()
    let n = v.len()

    // Insertion sort on the copy
    let mut i = 1
    while i < n {
        let key = v[i]
        let mut j = i - 1
        while j >= 0 && v[j] > key {
            v[j + 1] = v[j]
            j = j - 1
        }
        v[j + 1] = key
        i = i + 1
    }

    if n % 2 == 1 {
        return v[n / 2]
    } else {
        return (v[n / 2 - 1] + v[n / 2]) / 2.0
    }
}

fn pascal(n: Int) -> [Int] {
    let mut row: [Int] = [1]
    for i in 0..n {
        let mut next: [Int] = [1]
        for j in 0..(len(row) - 1) {
            next.push(row[j] + row[j + 1])
        }
        next.push(1)
        row = next
    }
    return row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    // Insertion sort by start into a new array
    let mut sorted: [(Int, Int)] = []
    for p in xs {
        let mut result: [(Int, Int)] = []
        let mut placed = false
        for q in sorted {
            if !placed and p.0 < q.0 {
                result.push(p)
                placed = true
            }
            result.push(q)
        }
        if !placed {
            result.push(p)
        }
        sorted = result
    }

    // Sweep, merging overlapping or touching intervals
    let mut merged: [(Int, Int)] = []
    for p in sorted {
        let n = len(merged)
        if n > 0 and p.0 <= merged[n - 1].1 {
            let last = merged[n - 1]
            merged[n - 1] = (last.0, max(last.1, p.1))
        } else {
            merged.push(p)
        }
    }
    return merged
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    if xs.len() == 0 {
        return fallback;
    }
    return xs[xs.len() - 1];
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let mut result: [(T, T)] = [];
    let n = len(xs);
    let mut i = 0;
    while i + 1 < n {
        result.push((xs[i], xs[i + 1]));
        i += 1;
    }
    result
}

fn names(xs: [Named]) -> String {
    let mut result = ""
    let mut first = true
    for x in xs {
        if first {
            first = false
        } else {
            result = result + ", "
        }
        result = result + x.name()
    }
    result
}

fn message(e: LoginError) -> String {
    match e {
        NoSuchUser(name) => "no user " + name,
        WrongPassword => "wrong password",
        Locked(minutes) => "locked for " + minutes.to_string() + " minutes",
    }
}

fn port_sum(text: String) -> Int ! PortError {
    let parts = text.split(":")
    if parts.len() != 2 {
        fail PortError.Bad(text: text)
    }
    let a = try parse_port(parts[0])
    let b = try parse_port(parts[1])
    a + b
}

fn city(u: User) -> String {
    return u.address?.city?.toUpperCase() ?? "UNKNOWN"
}

fn sum_squares(lo: Int, hi: Int) -> Int ! Error {
    let mut total = 0
    let mut i = lo
    while i <= hi {
        total = total + i * i
        i = i + 1
    }
    return total
}

fn squares(n: Int) -> Int ! Error {
    let mid = n / 2
    let first = spawn sum_squares(1, mid)
    let rest = spawn sum_squares(mid + 1, n)
    return await first + await rest
}

fn total_qty(text: String) -> Int {
    match json.decode<List<Item>>(text) {
        Ok(items) => {
            let mut total = 0
            for item in items {
                total = total + item.qty
            }
            total
        }
        Err(_) => -1
    }
}

fn total(items: [(Decimal, Int)]) -> Decimal {
    let mut sum = Decimal::zero()
    for (price, qty) in items {
        sum = sum + price * Decimal::from(qty)
    }
    sum
}

fn deposit(a: Account, amount: Int) -> Account {
    return a with { balance: a.balance + amount }
}

fn swap_ends(inout xs: [Int]) {
    let n = xs.len()
    if n < 2 {
        return
    }
    let first = xs[0]
    xs[0] = xs[n - 1]
    xs[n - 1] = first
}

fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    let result: [String] = []
    for (key, value) in m {
        if value >= min {
            result.push(key)
        }
    }
    result.sort()
    return result
}

fn numbered(items: [String]) -> String {
    let mut lines: [String] = []
    let mut n = 1
    for item in items {
        lines.push(n.to_string() + ". " + item)
        n = n + 1
    }
    return lines.join("\n")
}

fn add_or_none(a: Int, b: Int) -> Int? {
    return a.checked_add(b)
}

fn adder(step: Int) -> fn(Int) -> Int {
    return |x: Int| -> Int { x + step };
}

fn key_count(events: [Event]) -> Int {
    let mut count = 0
    for e in events {
        match e {
            Key(_) => count = count + 1,
            _ => {}
        }
    }
    count
}

fn csv(n: Int) -> String {
    let mut text = ""
    let mut i = 1
    while i <= n {
        if i > 1 {
            text = text + ","
        }
        text = text + i.to_string()
        i = i + 1
    }
    return text
}

fn strip_vowels(text: String) -> String {
    let mut result = String::new();
    for c in text.chars() {
        match c {
            'a' | 'e' | 'i' | 'o' | 'u' | 'A' | 'E' | 'I' | 'O' | 'U' => {}
            _ => result.push(c),
        }
    }
    result
}

fn is_power_of_two(n: Int) -> Bool {
    if n <= 0 {
        return false
    }
    return (n & (n - 1)) == 0
}

fn binary(n: Int) -> String {
    if n == 0 {
        return "0";
    }
    let mut m = n;
    let mut s = "";
    while m > 0 {
        if m % 2 == 1 {
            s = "1" + s;
        } else {
            s = "0" + s;
        }
        m = m / 2;
    }
    return s;
}

fn mode(xs: [Int]) -> Int {
    let mut best = xs[0];
    let mut best_count = 0;
    for x in xs {
        let mut c = 0;
        for y in xs {
            if y == x {
                c = c + 1;
            }
        }
        if c > best_count || (c == best_count && x < best) {
            best = x;
            best_count = c;
        }
    }
    return best;
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let mut result: [String: Int] = {}
    let n = min(len(keys), len(values))
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    return result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 || b <= 0 || c <= 0 {
        return "invalid"
    }
    if a >= b + c || b >= a + c || c >= a + b {
        return "invalid"
    }
    if a == b && b == c {
        return "equilateral"
    }
    if a == b || b == c || a == c {
        return "isosceles"
    }
    return "scalene"
}

fn lengths(text: String) -> [Int] {
    text.split(" ").map(|w| w.len())
}

fn collatz(n: Int) -> Int {
    let mut steps = 0
    let mut x = n
    while x != 1 {
        if x % 2 == 0 {
            x = x / 2
        } else {
            x = 3 * x + 1
        }
        steps = steps + 1
    }
    return steps
}

fn sum_digits(text: String) -> Int {
    let mut total: Int = 0;
    for c in text.chars() {
        if c >= '0' && c <= '9' {
            total = total + (c as Int) - ('0' as Int);
        }
    }
    return total;
}

fn top(players: [Player], k: Int) -> [String] {
    let mut sorted: [Player] = []
    for p in players {
        let mut i = len(sorted)
        sorted.push(p)
        while i > 0 && sorted[i - 1].score < p.score {
            sorted[i] = sorted[i - 1]
            i = i - 1
        }
        sorted[i] = p
    }

    let mut names: [String] = []
    let mut j = 0
    while j < k && j < len(sorted) {
        names.push(sorted[j].name)
        j = j + 1
    }
    return names
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int] {
    xs.map(|x| if x < lo { lo } else if x > hi { hi } else { x })
}

fn is_sorted(xs: [Int]) -> Bool {
    let n = len(xs)
    let mut i = 1
    while i < n {
        if xs[i - 1] > xs[i] {
            return false
        }
        i = i + 1
    }
    return true
}

fn hex_digit(n: Int) -> String {
    let digits = "0123456789abcdef"
    return digits[n]
}

fn hex_byte(v: Int) -> String {
    let hi = v / 16
    let lo = v % 16
    return hex_digit(hi) + hex_digit(lo)
}

fn hex(r: Int, g: Int, b: Int) -> String {
    return "#" + hex_byte(r) + hex_byte(g) + hex_byte(b)
}

fn simulate(commands: [Int]) -> [Int] {
    let mut queue: [Int] = []
    for cmd in commands {
        if cmd > 0 {
            queue.push(cmd)
        } else if cmd == 0 {
            if queue.len() > 0 {
                queue.remove(0)
            }
        }
    }
    return queue
}

fn sum_evens(xs: [Int]) -> Int {
    let total = 0
    for x in xs {
        if x % 2 == 0 {
            total += x
        }
    }
    total
}

fn reverse_words(text: String) -> String {
    const parts = text.replace(" ", "\n").lines()
    let result: [String] = []
    let i = parts.count()
    while i > 0 {
        i -= 1
        result.push(parts[i])
    }
    result.join(" ")
}

fn is_palindrome(text: String) -> Bool {
    const folded = text.lower()
    let left = 0
    let right = folded.length - 1
    let result = true
    while left < right and result {
        if folded.slice(left, left + 1) != folded.slice(right, right + 1) {
            result = false
        } else {
            left += 1
            right -= 1
        }
    }
    result
}

fn count_vowels(text: String) -> Int {
    let count = 0
    for ch in text.chars() {
        if ch == "a" or ch == "e" or ch == "i" or ch == "o" or ch == "u" or ch == "A" or ch == "E" or ch == "I" or ch == "O" or ch == "U" {
            count += 1
        }
    }
    count
}

fn fizzbuzz(n: Int) -> String {
    if n % 15 == 0 {
        "FizzBuzz"
    } else if n % 3 == 0 {
        "Fizz"
    } else if n % 5 == 0 {
