fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.count()
    let result: Int? = none
    while lo < hi and result == none {
        const mid = lo + (hi - lo) / 2
        if xs[mid] == target {
            result = mid
        } else if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    result
}

