    for candidate in 2..n {
        let is_prime = true
        let divisor = 2
        while divisor * divisor <= candidate {
            if candidate % divisor == 0 {
                is_prime = false
                break
            }
            divisor += 1
        }
        if is_prime {
            primes.push(candidate)
        }
    }
    primes
}

