    let ok = true
    for ch in text {
        if ch == "(" or ch == "[" or ch == "{" {
            stack.push(ch)
        } else if ch == ")" or ch == "]" or ch == "}" {
            const expected = if ch == ")" { "(" } else if ch == "]" { "[" } else { "{" }
            const open = stack.pop() ?? ""
            if open != expected {
                ok = false
            }
        }
    }
    ok and stack.count() == 0
}

