fn distance(a: String, b: String) -> Int {
    const n = b.len()
    let prev: [Int] = []
    for j in 0..n + 1 {
        prev.push(j)
    }
    for i in 1..a.len() + 1 {
        let cur: [Int] = [i]
        const ca = a.slice(i - 1, i)
        for j in 1..n + 1 {
            const cost = if ca == b.slice(j - 1, j) { 0 } else { 1 }
            const del = prev[j] + 1
            const ins = cur[j - 1] + 1
            const sub = prev[j - 1] + cost
            let best = if del < ins { del } else { ins }
            best = if best < sub { best } else { sub }
            cur.push(best)
        }
        prev = cur
    }
    prev[n]
}

