fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by(p => p.0)
    let out: [(Int, Int)] = []
    let cur_start = 0
    let cur_end = 0
    let active = false
    for (start, end) in sorted {
        if active and start <= cur_end {
            cur_end = if end > cur_end { end } else { cur_end }
        } else {
            if active {
                out = out + [(cur_start, cur_end)]
            }
            cur_start = start
            cur_end = end
            active = true
        }
    }
    if active {
        out = out + [(cur_start, cur_end)]
    }
    out
}

