fn gcd(a: Int, b: Int) -> Int
    require a > 0
    require b > 0
{
    let x = a
    let y = b
    while y != 0 {
        const r = x % y
        x = y
        y = r
    }
    x
}

fn title(text: String) -> String {
    const lower = "abcdefghijklmnopqrstuvwxyz"
    const upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let out = ""
    let at_word_start = true
    for i in 0..text.len() {
        const ch = text.slice(i, i + 1)
        if ch == " " {
            out += ch
            at_word_start = true
        } else {
            let letter_lower = ch
            let letter_upper = ch
            for k in 0..26 {
                if ch == lower.slice(k, k + 1) {
                    letter_upper = upper.slice(k, k + 1)
                }
                if ch == upper.slice(k, k + 1) {
                    letter_lower = lower.slice(k, k + 1)
                }
            }
            out += if at_word_start { letter_upper } else { letter_lower }
            at_word_start = false
        }
    }
    out
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else {
        let i = 2
        let prime = true
        while prime and i * i <= n {
            if n % i == 0 {
                prime = false
            }
            i += 1
        }
        prime
    }
}

fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    for candidate in 2..n {
        let is_prime = true
        let divisor = 2
        while divisor * divisor <= candidate and is_prime {
            if candidate % divisor == 0 {
                is_prime = false
            }
            divisor += 1
        }
        if is_prime {
            primes.push(candidate)
        }
    }
    primes
}

fn digit_sum(n: Int) -> Int
    require n >= 0
{
    let total = 0
    let rest = n
    while rest > 0 {
        total += rest % 10
        rest /= 10
    }
    total
}

fn rle(text: String) -> String {
    let out = ""
    let prev = ""
    let count = 0
    for ch in text.chars() {
        const current = "{ch}"
        if count > 0 and current == prev {
            count += 1
        } else {
            if count > 0 {
                out += "{prev}{count}"
            }
            prev = current
            count = 1
        }
    }
    if count > 0 {
        out += "{prev}{count}"
    }
    out
}

fn balanced(text: String) -> Bool {
    let stack: [Char] = []
    let ok = true
    for ch in text.chars() {
        if ch == '(' or ch == '[' or ch == '{' {
            stack.push(ch)
        } else {
            if ch == ')' or ch == ']' or ch == '}' {
                if stack.count() == 0 {
                    ok = false
                } else {
                    const top = stack[stack.count() - 1]
                    const expected = match ch {
                        ')' => '('
                        ']' => '['
                        _ => '{'
                    }
                    if top != expected {
                        ok = false
                    }
                    stack = stack.take(stack.count() - 1)
                }
            }
        }
    }
    ok and stack.count() == 0
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let result: (Int, Int)? = none
    for i in 0..xs.len() {
        for j in (i + 1)..xs.len() {
            if result == none and xs[i] + xs[j] == target {
                result = (i, j)
            }
        }
    }
    result
}

fn anagrams(a: String, b: String) -> Bool {
    // Assumes String.lower() and String.chars() -> [String], and List.sort().
    const left = a.lower().chars().sort()
    const right = b.lower().chars().sort()
    left == right
}

fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
{
    const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    const symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    let rest = n
    let out = ""
    for i in 0..13 {
        while rest >= values[i] {
            out += symbols[i]
            rest -= values[i]
        }
    }
    out
}

fn flatten(xss: [[Int]]) -> [Int] {
    let result: [Int] = []
    for xs in xss {
        for x in xs {
            result.push(x)
        }
    }
    result
}

fn chunks(xs: [Int], n: Int) -> [[Int]] {
    let total = 0
    for x in xs {
        total += 1
    }
    const groups = (total + n - 1) / n
    let out: [[Int]] = []
    for i in 0..groups {
        out.push(xs.skip(i * n).take(n))
    }
    out
}

fn rotate(xs: [Int], k: Int) -> [Int]
    require k >= 0
{
    let n = 0
    for _ in xs {
        n += 1
    }
    const m = if n == 0 { 0 } else { k % n }
    let out: [Int] = []
    for i in 0..n {
        out.push(xs[(i + m) % n])
    }
    out
}

fn common_prefix(words: [String]) -> String {
    let prefix = if words.len() == 0 { "" } else { words[0] }
    for word in words {
        while not (word.len() >= prefix.len() and word.slice(0, prefix.len()) == prefix) {
            prefix = prefix.slice(0, prefix.len() - 1)
        }
    }
    prefix
}

fn second_largest(xs: [Int]) -> Int? {
    let best = 0
    let second = 0
    let has_best = false
    let has_second = false
    for x in xs {
        if not has_best {
            best = x
            has_best = true
        } else if x > best {
            second = best
            has_second = true
            best = x
        } else if x < best and (not has_second or x > second) {
            second = x
            has_second = true
        }
    }
    if has_second { second } else { none }
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() or j < b.len() {
        if j >= b.len() or (i < a.len() and a[i] <= b[j]) {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const n = b.len()
    let prev: [Int] = []
    for j in 0..n + 1 {
        prev.push(j)
    }
    for i in 0..a.len() {
        let curr: [Int] = [i + 1]
        const ca = a.slice(i, i + 1)
        for j in 0..n {
            const cb = b.slice(j, j + 1)
            const cost = if ca == cb { 0 } else { 1 }
            const delete = prev[j + 1] + 1
            const insert = curr[j] + 1
            const substitute = prev[j] + cost
            const best = if delete < insert { delete } else { insert }
            const m = if substitute < best { substitute } else { best }
            curr.push(m)
        }
        prev = curr
    }
    prev[n]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        let all: [Int] = []
        for item in self.items {
            all.push(item)
        }
        all.push(x)
        Stack(items: all)
    }

    fn pop(self) -> Stack {
        let kept: [Int] = []
        let last: Int? = none
        for item in self.items {
            if let prev = last {
                kept.push(prev)
            }
            last = item
        }
        Stack(items: kept)
    }

    fn top(self) -> Int? {
        let last: Int? = none
        for item in self.items {
            last = item
        }
        last
    }
}

fn count_char(text: String, c: Char) -> Int {
    let total = 0
    for ch in text.chars() {
        if ch == c {
            total += 1
        }
    }
    total
}

fn median(xs: [Float]) -> Float
    require xs.count(x => true) > 0
{
    const sorted = xs.sort()
    const n = xs.count(x => true)
    const mid = n / 2
    if n % 2 != 0 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

fn pascal(n: Int) -> [Int] {
    let row = [1]
    for i in 0..n {
        let next = [1]
        for k in 1..i + 1 {
            next.push(row[k - 1] + row[k])
        }
        next.push(1)
        row = next
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by(p => p.0)
    let out: [(Int, Int)] = []
    let has_current = false
    let cur_start = 0
    let cur_end = 0
    for (start, end) in sorted {
        if has_current and start <= cur_end {
            if end > cur_end {
                cur_end = end
            }
        } else {
            if has_current {
                out.push((cur_start, cur_end))
            }
            has_current = true
            cur_start = start
            cur_end = end
        }
    }
    if has_current {
        out.push((cur_start, cur_end))
    }
    out
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    let found = fallback
    for x in xs {
        found = x
    }
    found
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let result: [(T, T)] = []
    let prev: T? = none
    for x in xs {
        if let p = prev {
            result.push((p, x))
        }
        prev = x
    }
    result
}

