fn squares(n: Int) -> Int ! Error {
    const mid = n / 2
    const rest_start = mid + 1
    const end = n + 1

    let first = 0
    for i in 1..rest_start {
        first += i * i
    }

    let second = 0
    for i in rest_start..end {
        second += i * i
    }

    first + second
}

