        .take(k)
        .map(p => p.name)
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int] {
    xs.map(x => if x < lo { lo } else { if x > hi { hi } else { x } })
}

fn is_sorted(xs: [Int]) -> Bool {
    let ok = true
    let prev: Int? = none
    for x in xs {
        if let p = prev {
            if x < p {
                ok = false
            }
        }
        prev = x
    }
    ok
}

fn simulate(commands: [Int]) -> [Int] {
    let items: [Int] = []
    let size = 0
    let head = 0
    for command in commands {
        if command > 0 {
            items.push(command)
            size += 1
        } else if command == 0 and head < size {
            head += 1
        }
    }
    let result: [Int] = []
    let index = 0
    for item in items {
        if index >= head {
            result.push(item)
        }
        index += 1
    }
    result
}

fn sum_evens(xs: [Int]) -> Int {
    let total = 0
    for x in xs {
        if x % 2 == 0 {
            total += x
        }
    }
    total
}

fn reverse_words(text: String) -> String {
    const parts = text.split(" ")
    let result = ""
    let i = parts.len() - 1
    while i >= 0 {
        if i < parts.len() - 1 {
            result += " "
        }
        result += parts[i]
        i -= 1
    }
    result
}

fn is_palindrome(text: String) -> Bool {
    const folded = text.lower()
    const chars = folded.chars()
    chars == chars.reverse()
}

fn count_vowels(text: String) -> Int {
    const vowels = Set.of("a", "e", "i", "o", "u")
    let count = 0
    for ch in text.lower().chars() {
        if vowels.contains(String(ch)) {
            count += 1
        }
    }
    count
}

fn fizzbuzz(n: Int) -> String {
    if n % 15 == 0 {
        "FizzBuzz"
    } else if n % 3 == 0 {
        "Fizz"
    } else if n % 5 == 0 {
        "Buzz"
    } else {
