fn factorial(n: Int) -> Int
    require n >= 0 and n <= 20
    ensure result >= 1
{
    let acc = 1
    for i in 1..n + 1 {
        acc *= i
    }
    acc
}

fn fib(n: Int) -> Int {
    let a = 0
    let b = 1
    for _ in 0..n {
        const next = a + b
        a = b
        b = next
    }
    a
}

fn by_length(words: [String]) -> [String] {
    let out: [String] = []
    for word in words {
        let pos = out.len()
        let i = 0
        while i < out.len() {
            if out[i].len() > word.len() {
                pos = i
                break
            }
            i += 1
        }
        let next: [String] = []
        let j = 0
        for item in out {
            if j == pos {
                next.push(word)
            }
            next.push(item)
            j += 1
        }
        if pos == out.len() {
            next.push(word)
        }
        out = next
    }
    out
}

fn dedupe(xs: [Int]) -> [Int] {
    let seen: Set<Int> = Set.of()
    let out: [Int] = []
    for x in xs {
        if not seen.contains(x) {
            seen.add(x)
            out.push(x)
        }
    }
    out
}

fn total_area(rects: [Rect]) -> Float {
    let total = 0.0
    for r in rects {
        total += r.width * r.height
    }
    total
}

fn area(s: Shape) -> Float {
    match s {
        Shape.Circle(radius) => 3.14 * radius * radius
        Shape.Square(side) => side * side
    }
}

fn first_negative(xs: [Int]) -> Int? {
    let found: Int? = none
    let i = 0
    for x in xs {
        if found == none and x < 0 {
            found = i
        }
        i += 1
    }
    found
}

fn caesar(text: String, k: Int) -> String {
    const alphabet = "abcdefghijklmnopqrstuvwxyz".chars()
    let out = ""
    for ch in text.chars() {
        let shifted = ch
        for i in 0..26 {
            if ch == alphabet[i] {
                shifted = alphabet[(i + k) % 26]
            }
        }
        out += String(shifted)
    }
    out
}

fn transpose(m: [[Int]]) -> [[Int]] {
    const rows = m.len()
    const cols = m[0].len()
    let result: [[Int]] = []
    for j in 0..cols {
        let row: [Int] = []
        for i in 0..rows {
            row.push(m[i][j])
        }
        result.push(row)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    let result: Int? = none
    while lo < hi and result == none {
        const mid = lo + (hi - lo) / 2
        if xs[mid] == target {
            result = mid
        } else if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    result
}

pub fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail MathError.DivideByZero
    }
    a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let groups: [String: [String]] = [:]
    for word in words {
        const letter = word.slice(0, 1)
        let items = groups[letter] ?? []
        items.push(word)
        groups[letter] = items
    }
    groups
}

fn running(xs: [Int]) -> [Int] {
    let total = 0
    let out: [Int] = []
    for x in xs {
        total += x
        out.push(total)
    }
    out
}

fn gcd(a: Int, b: Int) -> Int {
    let x = a
    let y = b
    while y != 0 {
        const r = x % y
        x = y
        y = r
    }
    x
}

fn title(text: String) -> String {
    const words = text.split(" ")
    const cased = words.map(w => {
        if w.len() == 0 {
            w
        } else {
            w.slice(0, 1).upper() + w.slice(1, w.len()).lower()
        }
    })
    cased.join(" ")
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else if n < 4 {
        true
    } else if n % 2 == 0 {
        false
    } else {
        let d = 3
        let prime = true
        while prime and d * d <= n {
            if n % d == 0 {
                prime = false
            }
            d += 2
        }
        prime
    }
}

fn is_prime(k: Int) -> Bool {
    let d = 2
    let prime = k >= 2
    while prime and d * d <= k {
        if k % d == 0 {
            prime = false
        }
        d += 1
    }
    prime
}

fn primes_below(n: Int) -> [Int] {
    let result: [Int] = []
    for k in 0..n {
        if is_prime(k) {
            result.push(k)
        }
    }
    result
}

fn digit_sum(n: Int) -> Int {
    let m = n
    let total = 0
    while m > 0 {
        total += m % 10
        m = m / 10
    }
    total
}

fn rle(text: String) -> String {
    let out = ""
    let prev: Char = ' '
    let count = 0
    for ch in text.chars() {
        if count > 0 and ch == prev {
            count += 1
        } else {
            if count > 0 {
                out += "{prev}{count}"
            }
            prev = ch
            count = 1
        }
    }
    if count > 0 {
        out += "{prev}{count}"
    }
    out
}

fn balanced(text: String) -> Bool {
    let stack: [Char] = []
    let ok = true
    for ch in text.chars() {
        if ch == '(' or ch == '[' or ch == '{' {
            stack.push(ch)
        } else if ch == ')' or ch == ']' or ch == '}' {
            if stack.len() == 0 {
                ok = false
            } else {
                const top = stack[stack.len() - 1]
                const want = if ch == ')' { '(' } else if ch == ']' { '[' } else { '{' }
                if top != want {
                    ok = false
                }
                let kept: [Char] = []
                for i in 0..stack.len() - 1 {
                    kept.push(stack[i])
                }
                stack = kept
            }
        }
    }
    ok and stack.len() == 0
}

