fn distance(a: String, b: String) -> Int {
    const s = a.chars()
    const t = b.chars()
    let prev: [Int] = []
    for j in 0..t.len() + 1 {
        prev.push(j)
    }
    for i in 0..s.len() {
        let curr: [Int] = [i + 1]
        for j in 0..t.len() {
            const cost = if s[i] == t[j] { 0 } else { 1 }
            const del = prev[j + 1] + 1
            const ins = curr[j] + 1
            const sub = prev[j] + cost
            const best = if del < ins { del } else { ins }
            curr.push(if best < sub { best } else { sub })
        }
        prev = curr
    }
    prev[t.len()]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        let all = self.items
        all.push(x)
        Stack(items: all)
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            self
        } else {
            self with { items: self.items.take(self.items.len() - 1) }
        }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            none
        } else {
            self.items[self.items.len() - 1]
        }
    }
}

