fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by(p => p.0)
    let out: [(Int, Int)] = []
    let has_cur = false
    let cur_s = 0
    let cur_e = 0
    for iv in sorted {
        if not has_cur {
            cur_s = iv.0
            cur_e = iv.1
            has_cur = true
        } else if iv.0 <= cur_e {
            if iv.1 > cur_e {
                cur_e = iv.1
            }
        } else {
            out.push((cur_s, cur_e))
            cur_s = iv.0
            cur_e = iv.1
        }
    }
    if has_cur {
        out.push((cur_s, cur_e))
    }
    out
}

