fn primes_below(n: Int) -> [Int] {
    let mut primes: [Int] = [];
    let mut i: Int = 2;

    while i < n {
        let mut is_prime: Bool = true;
        let mut j: Int = 0;

        while j < len(primes) {
            let p: Int = primes[j];
            if p * p > i {
                break;
            }
            if i % p == 0 {
                is_prime = false;
                break;
            }
            j = j + 1;
