    let mut current: Option<char> = None;
    let mut count: usize = 0;

    for c in text.chars() {
        match current {
            Some(p) if p == c => {
                count += 1;
            }
            Some(p) => {
                result.push(p);
                result.push_str(&count.to_string());
                current = Some(c);
                count = 1;
            }
            None => {
                current = Some(c);
                count = 1;
            }
        }
    }

    if let Some(p) = current {
        result.push(p);
        result.push_str(&count.to_string());
    }

    result
}

fn balanced(text: String) -> Bool {
    let mut stack: List<Char> = [];

    for c in text.chars() {
        if c == '(' || c == '[' || c == '{' {
            stack.push(c);
        } else if c == ')' || c == ']' || c == '}' {
            if stack.is_empty() {
                return false;
            }
            let open = stack.pop();
            if (c == ')' && open != '(') ||
