fn distance(a: String, b: String) -> Int {
    let n: Int = len(a);
    let m: Int = len(b);

    if n == 0 {
        return m;
    }
    if m == 0 {
        return n;
    }

    // prev[j] = distance between the first i-1 chars of a and the first j chars of b
    let mut prev: List<Int> = [];
    let mut j: Int = 0;
    while j <= m {
        push(prev, j);
        j = j + 1;
    }

    let mut i: Int = 1;
    while i <= n {
        let mut curr: List<Int> = [];
        push(curr, i);

        let mut k: Int = 1;
        while k <= m {
            let cost: Int = if char_at(a, i - 1) == char_at(b, k - 1) { 0 } else { 1 };

            let deletion: Int = prev[k] + 1;
            let insertion: Int = curr[k - 1] + 1;
            let substitution: Int = prev[k - 1] + cost;

            let mut best: Int = deletion;
            if insertion < best {
                best = insertion;
            }
            if substitution < best {
                best = substitution;
            }

            push(curr, best);
            k = k + 1;
        }

        prev = curr;
        i = i + 1;
    }

    return prev[m];
}

