fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let mut sorted = xs;

    // Insertion sort by start
    let mut i = 1;
    while i < len(sorted) {
        let key = sorted[i];
        let mut j = i;
        while j > 0 && sorted[j - 1].0 > key.0 {
            sorted[j] = sorted[j - 1];
            j = j - 1;
        }
        sorted[j] = key;
        i = i + 1;
    }

    let mut result: [(Int, Int)] = [];
    if len(sorted) == 0 {
        return result;
    }

    let mut cur = sorted[0];
    let mut k = 1;
    while k < len(sorted) {
        let next = sorted[k];
        if next.0 <= cur.1 {
            // Overlapping or touching: extend the current interval
            if next.1 > cur.1 {
                cur = (cur.0, next.1);
            }
        } else {
            result.push(cur);
            cur = next;
        }
        k = k + 1;
    }
    result.push(cur);

    return result;
}

