fn find(xs: [Int], target: Int) -> Int? {
    let low = 0
    let high = xs.len() - 1
    let result: Int? = none
    while low <= high {
        const mid = low + (high - low) / 2
        const value = xs[mid]
        if value == target {
            result = mid
            break
        } else if value < target {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    result
}

