fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let run = 0
    for ch in text.chars() {
        const c = "{ch}"
        if run > 0 and c == current {
            run += 1
        } else {
            if run > 0 {
                result += "{current}{run}"
            }
            current = c
            run = 1
        }
    }
    if run > 0 {
        result += "{current}{run}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for ch in text.chars() {
        if ch == "(" {
            stack = stack + [")"]
        } else if ch == "[" {
            stack = stack + ["]"]
        } else if ch == "{" {
            stack = stack + ["}"]
        } else if ch == ")" or ch == "]" or ch == "}" {
            const size = stack.len()
            if size == 0 {
                ok = false
            } else if stack[size - 1] != ch {
                ok = false
            } else {
                stack = stack.take(size - 1)
            }
        }
    }
    ok and stack.len() == 0
}

