fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()
    const m = ys.len()
    let prev: [Int] = []
    for j in 0..(m + 1) {
        prev.push(j)
    }
    for i in 0..xs.len() {
        let curr: [Int] = [i + 1]
        for j in 0..m {
            const cost = if xs[i] == ys[j] { 0 } else { 1 }
            curr.push(smallest(prev[j] + cost, prev[j + 1] + 1, curr[j] + 1))
        }
        prev = curr
    }
    prev[m]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        Stack(items: self.items + [x])
    }

    fn pop(self) -> Stack {
        const n = self.items.count()
        if n == 0 {
            self
        } else {
            Stack(items: self.items.take(n - 1))
        }
    }

    fn top(self) -> Int? {
        const n = self.items.count()
        if n == 0 {
            none
        } else {
            self.items[n - 1]
        }
    }
}

