fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by(p => p.0)
    let result: [(Int, Int)] = []
    let current: (Int, Int)? = none
    for (s, e) in sorted {
        if let c = current {
            if s <= c.1 {
                const new_end = if e > c.1 { e } else { c.1 }
                current = (c.0, new_end)
            } else {
                result.push(c)
                current = (s, e)
            }
        } else {
            current = (s, e)
        }
    }
    if let last = current {
        result.push(last)
    }
    result
}

