fn find(xs: [Int], target: Int) -> Int? {
    let low = 0
    let high = xs.len()
    let found = false
    let result: Int? = none
    while low < high and not found {
        const mid = low + (high - low) / 2
        if xs[mid] == target {
            result = mid
            found = true
        } else if xs[mid] < target {
            low = mid + 1
        } else {
            high = mid
        }
    }
    result
}

