fn title(text: String) -> String {
    const letter_pairs = [
        ("a", "A"), ("b", "B"), ("c", "C"), ("d", "D"), ("e", "E"),
        ("f", "F"), ("g", "G"), ("h", "H"), ("i", "I"), ("j", "J"),
        ("k", "K"), ("l", "L"), ("m", "M"), ("n", "N"), ("o", "O"),
        ("p", "P"), ("q", "Q"), ("r", "R"), ("s", "S"), ("t", "T"),
        ("u", "U"), ("v", "V"), ("w", "W"), ("x", "X"), ("y", "Y"),
        ("z", "Z")
    ]
    let lowered = text
    for (lower, upper) in letter_pairs {
        lowered = lowered.replace(upper, lower)
    }
    let spaced = " " + lowered
    for (lower, upper) in letter_pairs {
        spaced = spaced.replace(" {lower}", " {upper}")
    }
    spaced.slice(1, spaced.len())
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else {
        let divisor = 2
        let found = false
        while not found and divisor <= n / divisor {
            if n % divisor == 0 {
                found = true
            }
            divisor += 1
        }
        not found
    }
}

fn primes_below(n: Int) -> [Int] {
    let result: [Int] = []
    for candidate in 2..n {
        let is_prime = true
        let divisor = 2
        while is_prime and divisor * divisor <= candidate {
            if candidate % divisor == 0 {
                is_prime = false
            }
            divisor += 1
        }
        if is_prime {
            result.push(candidate)
        }
    }
    result
}

pub fn digit_sum(n: Int) -> Int
    require n >= 0
    example digit_sum(0) == 0
    example digit_sum(123) == 6
{
    let total = 0
    let rest = n
    while rest > 0 {
        total += rest % 10
        rest = rest / 10
    }
    total
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let run = 0
    for ch in text.chars() {
        const c = "{ch}"
        if run > 0 and c == current {
            run += 1
        } else {
            if run > 0 {
                result = result + "{current}{run}"
            }
            current = c
            run = 1
        }
    }
    if run > 0 {
        result = result + "{current}{run}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [Char] = []
    let ok = true
    for c in text.chars() {
        if c == '(' {
            stack.push(')')
        } else if c == '[' {
            stack.push(']')
        } else if c == '{' {
            stack.push('}')
        } else if c == ')' or c == ']' or c == '}' {
            if stack.len() == 0 {
                ok = false
                break
            }
            if stack[stack.len() - 1] != c {
                ok = false
                break
            }
            stack = stack.take(stack.len() - 1)
        }
    }
    ok and stack.len() == 0
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
