fn median(xs: [Float]) -> Float
    require xs.count(x => true) > 0
{
    const sorted = xs.sort()
    const n = sorted.count(x => true)
    const mid = n / 2
    if n % 2 != 0 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

fn pascal(n: Int) -> [Int]
    require n >= 0
{
    let row: [Int] = []
    let value = 1
    for k in 0..n + 1 {
        row.push(value)
        value = value * (n - k) / (k + 1)
    }
    row
}

pub fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by(p => p.0)
    let result: [(Int, Int)] = []
    let started = false
    let cur_start = 0
    let cur_end = 0
    for (s, e) in sorted {
        if not started {
            cur_start = s
            cur_end = e
            started = true
        } else if s <= cur_end {
            if e > cur_end {
                cur_end = e
            }
        } else {
            result.push((cur_start, cur_end))
            cur_start = s
            cur_end = e
        }
    }
    if started {
        result.push((cur_start, cur_end))
    }
    result
}

fn last_or<T>(xs: [T], fallback: T) -> T {
