fn mode(xs: [Int]) -> Int {
    const first = xs[0]
    let best = first
    let best_count = xs.count(y => y == first)
    for x in xs {
        const c = xs.count(y => y == x)
        if c > best_count or (c == best_count and x < best) {
            best = x
            best_count = c
        }
    }
    best
}

