    example triangle(3, 4, 5) == "scalene"
    example triangle(1, 2, 3) == "invalid"
    example triangle(0, 1, 1) == "invalid"
{
    if a <= 0 or b <= 0 or c <= 0 {
        "invalid"
    } else if a >= b + c or b >= a + c or c >= a + b {
        "invalid"
    } else if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

