pub fn find(xs: [Int], target: Int) -> Int?
    example find([1, 3, 5, 7], 5) == 2
    example find([1, 3, 5, 7], 4) == none
    example find([], 4) == none
{
    let lo = 0
    let hi = xs.len() - 1
    while lo <= hi {
        const mid = lo + (hi - lo) / 2
        const v = xs[mid]
        if v == target {
            return mid
        }
        if v < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    none
}

