pub fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
    example roman(1994) == "MCMXCIV"
    example roman(4) == "IV"
    example roman(3999) == "MMMCMXCIX"
{
    const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    const symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    let rest = n
    let out = ""
    let i = 0
    while i < 13 {
        while rest >= values[i] {
            out = out + symbols[i]
            rest -= values[i]
        }
        i += 1
    }
    out
}

