    example common_prefix(["flower", "flow", "flight"]) == "fl"
    example common_prefix(["abc"]) == "abc"
    example common_prefix(["a", "b"]) == ""
{
    if words.len() == 0 {
        return ""
    }
    let prefix = words[0]
    for w in words {
        while not w.starts_with(prefix) {
            prefix = prefix.slice(0, prefix.len() - 1)
        }
    }
    prefix
}

pub fn second_largest(xs: [Int]) -> Int?
    example second_largest([1, 2, 3]) == 2
    example second_largest([5, 5]) == none
    example second_largest([]) == none
    example second_largest([3, 1, 3, 2]) == 2
{
    let best: Int? = none
    let second: Int? = none
    for x in xs {
        if let b = best {
            if x > b {
                second = best
                best = x
            } else if x < b {
                if let s = second {
                    if x > s {
                        second = x
                    }
                } else {
                    second = x
                }
            }
        } else {
            best = x
        }
    }
    second
}

pub fn merge(a: [Int], b: [Int]) -> [Int]
    example merge([1, 3, 5], [2, 4]) == [1, 2, 3, 4, 5]
    example merge([], [1]) == [1]
    example merge([1, 1], [1]) == [1, 1, 1]
{
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

pub fn distance(a: String, b: String) -> Int
    example distance("kitten", "sitting") == 3
    example distance("", "abc") == 3
    example distance("same", "same") == 0
{
    const xs = a.chars()
    const ys = b.chars()
    let prev: [Int] = []
    for j in 0..(ys.len() + 1) {
        prev.push(j)
    }
    for i in 1..(xs.len() + 1) {
        let cur: [Int] = [i]
        for j in 1..(ys.len() + 1) {
            const cost = if xs[i - 1] == ys[j - 1] { 0 } else { 1 }
            const del = prev[j] + 1
            const ins = cur[j - 1] + 1
            const sub = prev[j - 1] + cost
            let best = del
            if ins < best {
                best = ins
            }
            if sub < best {
                best = sub
            }
            cur.push(best)
        }
        prev = cur
    }
    prev[ys.len()]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        let all = self.items
        all.push(x)
        Stack(items: all)
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            self
        } else {
            Stack(items: self.items.take(self.items.len() - 1))
        }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            none
        } else {
            self.items[self.items.len() - 1]
        }
    }
}

