fn pascal(n: Int) -> [Int]
    require n >= 0 and n <= 66
    example pascal(0) == [1]
    example pascal(1) == [1, 1]
    example pascal(4) == [1, 4, 6, 4, 1]
{
    let row = [1]
    for _ in 0..n {
        let next = [1]
        for j in 1..row.len() {
            next.push(row[j - 1] + row[j])
        }
        next.push(1)
        row = next
    }
    row
}

pub fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)]
    example merge_intervals([(1, 3), (2, 6), (8, 10), (6, 7)]) == [(1, 7), (8, 10)]
    example merge_intervals([(5, 6), (1, 5)]) == [(1, 6)]
    example merge_intervals([]) == []
{
    const sorted = xs.sort_by(p => p.0)
    let result: [(Int, Int)] = []
    for (s, e) in sorted {
        const n = result.len()
        if n > 0 and s <= result[n - 1].1 {
            const (ps, pe) = result[n - 1]
            result[n - 1] = (ps, if e > pe { e } else { pe })
        } else {
            result.push((s, e))
        }
    }
    result
}

