fn percent(part: Int, whole: Int) -> Int
    require whole > 0
    require part >= 0 and part <= whole
    ensure result >= 0 and result <= 100
    example percent(1, 3) == 33
    example percent(5, 5) == 100
    example percent(0, 7) == 0
    example percent(99, 100) == 99
{
    // Largest p in 0..100 with p * whole <= 100 * part, computed without overflow.
    const q = whole / 100
    const r = whole % 100
    let result = 0
    for p in 1..101 {
        const needed = p * q + (p * r + 99) / 100
        if needed <= part {
            result = p
        }
    }
    result
}

