fn by_length(words: [String]) -> [String] {
    let mut result = words.clone();
    let mut i = 1;
    while i < result.len() {
        let current = result[i].clone();
        let mut j = i;
        while j > 0 && result[j - 1].len() > current.len() {
            result[j] = result[j - 1].clone();
            j = j - 1;
        }
        result[j] = current;
        i = i + 1;
    }
    return result;
}

fn dedupe(xs: [Int]) -> [Int] {
    let mut result: [Int] = [];
    for x in xs {
        let mut seen = false;
        for y in result {
            if x == y {
                seen = true;
                break;
            }
        }
        if !seen {
            result.push(x);
        }
    }
    return result;
}

