fn balanced(text: String) -> Bool {
    let mut stack: Vec<Char> = Vec::new();

    for c in text.chars() {
        if c == '(' || c == '[' || c == '{' {
            stack.push(c);
        } else if c == ')' || c == ']' || c == '}' {
            let expected = if c == ')' {
                '('
            } else if c == ']' {
                '['
            } else {
                '{'
            };

            match stack.pop() {
                Some(open) => {
                    if open != expected {
                        return false;
                    }
                }
                None => {
                    return false;
                }
            }
        }
    }

    return stack.is_empty();
}

