fn distance(a: String, b: String) -> Int {
    let xs = a.chars();
    let ys = b.chars();
    let n = xs.len();
    let m = ys.len();

    let mut prev: Array<Int> = [];
    let mut j = 0;
    while j <= m {
        prev.push(j);
        j = j + 1;
    }

    let mut i = 1;
    while i <= n {
        let mut curr: Array<Int> = [i];
        let mut j = 1;
        while j <= m {
            let cost = if xs[i - 1] == ys[j - 1] { 0 } else { 1 };
            let del = prev[j] + 1;
            let ins = curr[j - 1] + 1;
            let sub = prev[j - 1] + cost;
            let mut best = del;
            if ins < best { best = ins; }
            if sub < best { best = sub; }
            curr.push(best);
            j = j + 1;
        }
        prev = curr;
        i = i + 1;
    }

    prev[m]
}

