fn median(xs: [Float]) -> Float {
    let n = len(xs);
    let mut s = xs;          // assumes this makes a copy

    // insertion sort
    let mut i = 1;
    while i < n {
        let key = s[i];
        let mut j = i;
        while j > 0 && s[j - 1] > key {
            s[j] = s[j - 1];
            j = j - 1;
        }
        s[j] = key;
        i = i + 1;
    }

    if n % 2 == 1 {
        return s[n / 2];
    } else {
        return (s[n / 2 - 1] + s[n / 2]) / 2.0;
    }
}

