fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let mut sorted = xs;

    // Insertion sort by start
    let mut i = 1;
    while i < len(sorted) {
        let mut j = i;
        while j > 0 && sorted[j - 1].0 > sorted[j].0 {
            let tmp = sorted[j - 1];
            sorted[j - 1] = sorted[j];
            sorted[j] = tmp;
            j = j - 1;
        }
        i = i + 1;
    }

    // Merge overlapping or touching intervals
    let mut result: [(Int, Int)] = [];
    for (s, e) in sorted {
        if len(result) > 0 && s <= result[len(result) - 1].1 {
            let last = len(result) - 1;
            if e > result[last].1 {
                result[last] = (result[last].0, e);
            }
        } else {
            result.push((s, e));
        }
    }
    result
}

