fn by_length(words: [String]) -> [String] {
    let result = words
    let i = 1
    while i < result.length {
        const current = result[i]
        let j = i
        while j > 0 and result[j - 1].length > current.length {
            result[j] = result[j - 1]
            j -= 1
        }
        result[j] = current
        i += 1
    }
    result
}

fn dedupe(xs: [Int]) -> [Int] {
