fn caesar(text: String, k: Int) -> String {
    const alphabet = "abcdefghijklmnopqrstuvwxyz"
    let shift: [String: String] = [:]
    for i in 0..26 {
        const j = (i + k) % 26
        shift[alphabet.slice(i, i + 1)] = alphabet.slice(j, j + 1)
    }
    let result = ""
    for ch in text.chars() {
        const s = "{ch}"
        const out = shift[s] ?? s
        result = "{result}{out}"
    }
    result
}

fn transpose(m: [[Int]]) -> [[Int]]
    require m.len() > 0
{
    const cols = m[0].len()
    let result: [[Int]] = []
    for j in 0..cols {
        let column: [Int] = []
        for row in m {
            column.append(row[j])
        }
        result.append(column)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    let found: Int? = none
    let searching = true
    while searching and lo < hi {
        const mid = lo + (hi - lo) / 2
        const value = xs[mid]
        if value == target {
            found = mid
            searching = false
        } else if value < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    found
}

