fn is_prime(n: Int) -> Bool {
    let prime = n >= 2
    let i = 2
    while prime and i <= n / i {
        if n % i == 0 {
            prime = false
        }
        i += 1
    }
    prime
}

fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    let i = 2
    while i < n {
        let is_prime = true
        for p in primes {
            if is_prime and p * p <= i {
                if i % p == 0 {
                    is_prime = false
                }
            }
        }
        if is_prime {
            primes.push(i)
        }
        i += 1
    }
    primes
}

fn rle(text: String) -> String {
    let result = ""
    let prev = ""
    let count = 0
    for ch in text.chars() {
        const c = "{ch}"
        if count > 0 and c == prev {
            count += 1
        } else {
            if count > 0 {
                result += "{prev}{count}"
            }
            prev = c
            count = 1
        }
    }
    if count > 0 {
        result += "{prev}{count}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [String] = []
    let ok = true
    for ch in text.chars() {
        const c = String(ch)
        if c == "(" or c == "[" or c == "{" {
            stack.push(c)
        } else if c == ")" or c == "]" or c == "}" {
            const expected = if c == ")" { "(" } else if c == "]" { "[" } else { "{" }
            if let top = stack.pop() {
                if top != expected {
                    ok = false
                }
            } else {
                ok = false
            }
        }
    }
    ok and stack.len() == 0
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
