fn common_prefix(words: [String]) -> String {
    let prefix = ""
    let started = false
    for word in words {
        if not started {
            prefix = word
            started = true
        } else {
            let limit = prefix.len()
            if word.len() < limit {
                limit = word.len()
            }
            let i = 0
            while i < limit and prefix.slice(i, i + 1) == word.slice(i, i + 1) {
                i += 1
            }
            prefix = prefix.slice(0, i)
        }
    }
    prefix
}

fn second_largest(xs: [Int]) -> Int? {
    let largest: Int? = none
    let second: Int? = none
    for x in xs {
        if let top = largest {
            if x > top {
                second = largest
                largest = x
            } else if x < top {
                if let runner = second {
                    if x > runner {
                        second = x
                    }
                } else {
                    second = x
                }
            }
        } else {
            largest = x
        }
    }
    second
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()
    const n = xs.len()
    const m = ys.len()

    let prev: [Int] = []
    for j in 0..(m + 1) {
        prev.push(j)
    }

    for i in 1..(n + 1) {
        let curr: [Int] = [i]
        for j in 1..(m + 1) {
            const cost = if xs[i - 1] == ys[j - 1] { 0 } else { 1 }
            const deletion = prev[j] + 1
            const insertion = curr[j - 1] + 1
            const substitution = prev[j - 1] + cost
            let best = deletion
            if insertion < best {
                best = insertion
            }
            if substitution < best {
                best = substitution
            }
            curr.push(best)
        }
        prev = curr
    }

    prev[m]
}

