    }
}

fn binomial(n: Int, k: Int) -> Int
    require k >= 0 and k <= n
{
    const m = if k < n - k { k } else { n - k }
    let c = 1
    let i = 0
    while i < m {
        c = c * (n - i) / (i + 1)
        i += 1
    }
    c
}

fn pascal(n: Int) -> [Int]
    require n >= 0
{
    let row: [Int] = []
    let k = 0
    while k <= n {
        row.push(binomial(n, k))
        k += 1
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let result: [(Int, Int)] = []
    let has_current = false
    let cur_start = 0
    let cur_end = 0
    for (start, end) in xs.sort() {
        if not has_current {
            cur_start = start
            cur_end = end
            has_current = true
        } else if start <= cur_end {
            if end > cur_end {
                cur_end = end
            }
        } else {
            result.push((cur_start, cur_end))
            cur_start = start
            cur_end = end
        }
    }
    if has_current {
        result.push((cur_start, cur_end))
    }
    result
}

fn last_or<T>(xs: [T], fallback: T) -> T {
