// NOTE: the Kavach guide does not cover concurrency, so `spawn` and
// `.join()` below are assumed syntax. Check docs/spec/ for the real
// task API and whether it needs a capability in `uses`.
// The guide also doesn't say whether `a..b` includes `b`. This code
// assumes it excludes `b`, as in `for i in 0..10`.

fn sum_squares(from: Int, to: Int) -> Int
    require from <= to
    example sum_squares(1, 4) == 14
{
    let total = 0
    for i in from..to {
        total += i * i
    }
    total
}

pub fn squares(n: Int) -> Int ! Error
    require n >= 0
    example squares(3) == 14
{
    const half = n / 2
    const first = spawn sum_squares(1, half + 1)
    const rest = spawn sum_squares(half + 1, n + 1)
    const a = try first.join()
    const b = try rest.join()
    a + b
}

