fn mode(xs: [Int]) -> Int {
    const sorted = xs.sort()
    let started = false
    let current = 0
    let run = 0
    let best = 0
    let best_count = 0
    for x in sorted {
        if started and x == current {
            run += 1
        } else {
            current = x
            run = 1
            started = true
        }
        if run > best_count {
            best_count = run
            best = current
        }
    }
    best
}

