fn caesar(text: String, k: Int) -> String {
    const letters = ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m",
        "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"]
    let out = ""
    for c in text.chars() {
        const s = "{c}"
        let shifted = s
        for i in 0..26 {
            if letters[i] == s {
                shifted = letters[(i + k) % 26]
            }
        }
        out += shifted
    }
    out
}

