fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    if lo < xs.len() {
        if xs[lo] == target {
            lo
        } else {
            none
        }
    } else {
        none
    }
}

