fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else {
        let prime = true
        let i = 2
        while prime and i <= n / i {
            if n % i == 0 {
                prime = false
            }
            i += 1
        }
        prime
    }
}

fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    for candidate in 2..n {
        let is_prime = true
        for p in primes {
            if p * p > candidate {
                break
            }
            if candidate % p == 0 {
                is_prime = false
                break
            }
        }
        if is_prime {
            primes.push(candidate)
        }
    }
    primes
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let run = 0
    for ch in text.chars() {
        const c = "{ch}"
        if run > 0 and c == current {
            run += 1
        } else {
            if run > 0 {
                result = "{result}{current}{run}"
            }
            current = c
            run = 1
        }
    }
    if run > 0 {
        result = "{result}{current}{run}"
    }
    result
}

fn balanced(text: String) -> Bool {
    let stack: [Char] = []
    let size = 0
    let depth = 0
    for ch in text.chars() {
        if ch == '(' or ch == '[' or ch == '{' {
            if depth < size {
                stack[depth] = ch
            } else {
                stack.push(ch)
                size += 1
            }
            depth += 1
        } else if ch == ')' or ch == ']' or ch == '}' {
            if depth == 0 {
                return false
            }
            const expected = if ch == ')' { '(' } else if ch == ']' { '[' } else { '{' }
            if stack[depth - 1] != expected {
                return false
            }
            depth -= 1
        }
    }
    depth == 0
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    const n = xs.len()
    let result: (Int, Int)? = none
    let found = false
    let i = 0
    while not found and i < n {
        let j = i + 1
        while not found and j < n {
            if xs[i] + xs[j] == target {
                result = (i, j)
                found = true
            }
            j += 1
        }
        i += 1
    }
    result
}

