        }
    }
    second
}

fn merge(a: [Int], b: [Int]) -> [Int]
    example merge([1, 3, 5], [2, 4, 6]) == [1, 2, 3, 4, 5, 6]
    example merge([], [1, 2]) == [1, 2]
    example merge([1, 1], []) == [1, 1]
{
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const xs = a.chars()
    const ys = b.chars()
    const n = xs.len()
    const m = ys.len()

    let prev: [Int] = []
    for j in 0..m + 1 {
        prev.push(j)
    }

    for i in 0..n {
        let curr: [Int] = [i + 1]
        for j in 0..m {
            const cost = if xs[i] == ys[j] { 0 } else { 1 }
            const deletion = prev[j + 1] + 1
            const insertion = curr[j] + 1
            const substitution = prev[j] + cost
            let best = deletion
            if insertion < best {
                best = insertion
            }
            if substitution < best {
                best = substitution
            }
            curr.push(best)
        }
        prev = curr
    }

    prev[m]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        let all = [x]
        for item in self.items {
            all.push(item)
        }
        self with { items: all }
    }

    fn pop(self) -> Stack {
        if let _ = self.top() {
            self with { items: self.items.skip(1) }
        } else {
            self
        }
    }

    fn top(self) -> Int? {
        self.items.find(x => true)
    }
}

