    }
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort()
    let result: [(Int, Int)] = []
    let started = false
    let cur_lo = 0
    let cur_hi = 0
    for (lo, hi) in sorted {
        if not started {
            cur_lo = lo
            cur_hi = hi
            started = true
        } else if lo <= cur_hi {
            if hi > cur_hi {
                cur_hi = hi
            }
        } else {
            result.push((cur_lo, cur_hi))
            cur_lo = lo
            cur_hi = hi
        }
    }
    if started {
        result.push((cur_lo, cur_hi))
    }
    result
}

