fn squares(n: Int) -> Int ! Error {
    const limit = if n < 0 { 0 } else { n }
    const mid = limit / 2

    const first = spawn sum_squares(1, mid)
    const second = spawn sum_squares(mid + 1, limit)

    const low_part = try first.wait() context "summing the first half"
    const high_part = try second.wait() context "summing the second half"
    low_part + high_part
}

