{
    const alphabet = "abcdefghijklmnopqrstuvwxyz"
    let out = ""
    for c in text.chars() {
        const s = "{c}"
        if let i = alphabet.index_of(s) {
            out += alphabet.slice((i + k) % 26, (i + k) % 26 + 1)
        } else {
            out += s
        }
    }
    out
}

fn transpose(m: [[Int]]) -> [[Int]]
    require m.len() >= 1 and m.all(r => r.len() == m[0].len())
    example transpose([[1, 2, 3], [4, 5, 6]]) == [[1, 4], [2, 5], [3, 6]]
{
    let result: [[Int]] = []
    const cols = m[0].len()
    for j in 0..cols {
        let row: [Int] = []
        for r in m {
            row.push(r[j])
        }
        result.push(row)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int?
    example find([1, 3, 5, 7], 5) == 2
{
    let lo = 0
    let hi = xs.len()
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        if xs[mid] == target {
            return mid
        }
        if xs[mid] < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    none
}

