fn median(xs: [Float]) -> Float
    require xs.len() > 0
    example median([3.0, 1.0, 2.0]) == 2.0
    example median([4.0, 1.0, 3.0, 2.0]) == 2.5
{
    const sorted = xs.sort()
    const n = sorted.len()
    const mid = n / 2
    if n % 2 == 1 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

fn pascal(n: Int) -> [Int]
    require n >= 0 and n <= 66
    example pascal(0) == [1]
    example pascal(4) == [1, 4, 6, 4, 1]
{
    let row: [Int] = [1]
    for i in 1..(n + 1) {
        let next: [Int] = [1]
        for k in 1..i {
            next.push(row[k - 1] + row[k])
        }
        next.push(1)
        row = next
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)]
    example merge_intervals([(5, 6), (1, 3), (2, 4), (4, 5), (8, 9)]) == [(1, 6), (8, 9)]
    example merge_intervals([]) == []
{
    const sorted = xs.sort_by(p => p.0)
    let out: [(Int, Int)] = []
    let cur_s = 0
    let cur_e = 0
    let have = false
    for (s, e) in sorted {
        if not have {
            cur_s = s
            cur_e = e
            have = true
        } else if s <= cur_e {
            if e > cur_e {
                cur_e = e
            }
        } else {
            out.push((cur_s, cur_e))
            cur_s = s
            cur_e = e
        }
    }
    if have {
        out.push((cur_s, cur_e))
    }
    out
}

