fn percent(part: Int, whole: Int) -> Int
    require whole > 0
    require part >= 0 and part <= whole
    ensure result >= 0 and result <= 100
    example percent(1, 3) == 33
    example percent(5, 5) == 100
    example percent(0, 7) == 0
    example percent(2, 3) == 66
{
    // Computes floor(part * 100 / whole) without overflow:
    // long division over the bits of 100, keeping remainder < whole.
    const bits = [true, true, false, false, true, false, false]
    let q = 0
    let rem = 0
    for bit in bits {
        // double q and rem
        if rem >= whole - rem {
            q = q * 2 + 1
            rem = rem - (whole - rem)
        } else {
            q = q * 2
            rem = rem + rem
        }
        if bit {
            if rem >= whole - part {
                q += 1
                rem = rem - (whole - part)
            } else {
                rem = rem + part
            }
        }
    }
    q
}

