fn mode(xs: [Int]) -> Int
    require xs.len() > 0
    example mode([1, 2, 2, 3]) == 2
    example mode([3, 1, 3, 1]) == 1
    example mode([5]) == 5
{
    let best = xs[0]
    let best_count = 0
    for x in xs {
        let c = 0
        for y in xs {
            if y == x {
                c += 1
            }
        }
        if c > best_count or (c == best_count and x < best) {
            best = x
            best_count = c
        }
    }
    best
}

