}

fn triangle(a: Int, b: Int, c: Int) -> String
    example triangle(2, 2, 2) == "equilateral"
    example triangle(3, 3, 5) == "isosceles"
    example triangle(3, 4, 5) == "scalene"
    example triangle(1, 1, 2) == "invalid"
    example triangle(0, 0, 0) == "invalid"
    example triangle(-1, 2, 2) == "invalid"
{
    if a <= 0 or b <= 0 or c <= 0 {
        return "invalid"
    }
    // all positive, so subtraction cannot overflow
    if a - b >= c or b - a >= c or c - a >= b {
        return "invalid"
    }
    if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

