}

fn no_divisor_from(n: Int, i: Int) -> Bool {
    if (i * i > n) { return true; }
    if (n % i == 0) { return false; }
    if (n % (i + 2) == 0) { return false; }
    return no_divisor_from(n, i + 6);
}

fn is_prime(n: Int) -> Bool {
    if (n < 2) { return false; }
    if (n < 4) { return true; }
    if (n % 2 == 0) { return false; }
    if (n % 3 == 0) { return false; }
    return no_divisor_from(n, 5);
}

fn primes_below(n: Int) -> [Int] {
    let mut primes: [Int] = [];
    let mut candidate = 2;
    while candidate < n {
        let mut is_prime = true;
        let mut i = 0;
        while i < primes.len() && primes[i] * primes[i] <= candidate {
            if candidate % primes[i] == 0 {
                is_prime = false;
                break;
            }
            i = i + 1;
        }
        if is_prime {
            primes.push(candidate);
        }
        candidate = candidate + 1;
    }
    return primes;
}

fn digit_sum(n: Int) -> Int {
    if n < 10 {
        return n;
    }
    return n % 10 + digit_sum(n / 10);
}

fn rle(text: String) -> String {
    let mut result = String::new();
    let mut chars = text.chars();

    let mut current = match chars.next() {
        Some(c) => c,
        None => return result,
    };
    let mut count: usize = 1;

    for c in chars {
        if c == current {
            count += 1;
        } else {
            result.push(current);
            result.push_str(&count.to_string());
            current = c;
            count = 1;
        }
    }

    result.push(current);
    result.push_str(&count.to_string());

    result
}

fn balanced(text: String) -> Bool {
    let mut stack: List<Char> = [];

    for c in text.chars() {
        if c == '(' {
            stack.push(')');
        } else if c == '[' {
            stack.push(']');
        } else if c == '{' {
            stack.push('}');
        } else if c == ')' || c == ']' || c == '}' {
            if stack.is_empty() {
                return false;
            }
            let expected = stack.pop();
            if expected != c {
                return false;
            }
        }
    }

    return stack.is_empty();
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let n = len(xs)
    var i = 0
    while i < n {
        var j = i + 1
        while j < n {
            if xs[i] + xs[j] == target {
                return (i, j)
            }
            j = j + 1
        }
        i = i + 1
    }
    return none
}

fn anagrams(a: String, b: String) -> Bool {
    let mut xs = a.to_lower().chars()
    let mut ys = b.to_lower().chars()
    xs.sort()
    ys.sort()
    return xs == ys
}

fn roman(n: Int) -> String {
    if (n >= 1000) { return "M" + roman(n - 1000); }
    if (n >= 900) { return "CM" + roman(n - 900); }
    if (n >= 500) { return "D" + roman(n - 500); }
    if (n >= 400) { return "CD" + roman(n - 400); }
    if (n >= 100) { return "C" + roman(n - 100); }
    if (n >= 90) { return "XC" + roman(n - 90); }
    if (n >= 50) { return "L" + roman(n - 50); }
    if (n >= 40) { return "XL" + roman(n - 40); }
    if (n >= 10) { return "X" + roman(n - 10); }
    if (n >= 9) { return "IX" + roman(n - 9); }
    if (n >= 5) { return "V" + roman(n - 5); }
    if (n >= 4) { return "IV" + roman(n - 4); }
    if (n >= 1) { return "I" + roman(n - 1); }
    return "";
}

fn flatten(xss: [[Int]]) -> [Int] {
    let mut result: [Int] = [];
    for xs in xss {
        for x in xs {
            result.push(x);
        }
    }
    return result;
}

fn chunks(xs: [Int], n: Int) -> [[Int]] {
    let mut result: [[Int]] = [];
    let mut current: [Int] = [];
    for x in xs {
        current.push(x);
        if current.len() == n {
            result.push(current);
            current = [];
        }
    }
    if current.len() > 0 {
        result.push(current);
    }
    return result;
}

fn rotate(xs: [Int], k: Int) -> [Int] {
    let n = len(xs)
    if n == 0 {
        return xs
    }
    let s = k % n
    var out: [Int] = []
    var i = 0
    while i < n {
        out.push(xs[(i + s) % n])
        i = i + 1
    }
    return out
}

fn common_prefix(words: &[String]) -> String {
    let Some(first) = words.first() else {
        return String::new();
    };
    let mut prefix: Vec<char> = first.chars().collect();
    for w in &words[1..] {
        let n = prefix
            .iter()
            .zip(w.chars())
            .take_while(|(a, b)| **a == *b)
            .count();
        prefix.truncate(n);
    }
    prefix.into_iter().collect()
}

fn second_largest(xs: [Int]) -> Int? {
    let mut has_first = false;
    let mut has_second = false;
    let mut first = 0;
    let mut second = 0;

    for x in xs {
        if !has_first {
            first = x;
            has_first = true;
        } else if x > first {
            second = first;
            has_second = true;
            first = x;
        } else if x < first && (!has_second || x > second) {
            second = x;
            has_second = true;
        }
    }

    if has_second {
        return second;
    }
    return none;
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let mut result: [Int] = [];
    let mut i = 0;
    let mut j = 0;

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i]);
            i = i + 1;
        } else {
            result.push(b[j]);
            j = j + 1;
        }
    }

    while i < a.len() {
        result.push(a[i]);
        i = i + 1;
    }

    while j < b.len() {
        result.push(b[j]);
        j = j + 1;
    }

    return result;
}

fn distance(a: String, b: String) -> Int {
    let s = a.chars();
    let t = b.chars();
    let n = s.len();
    let m = t.len();

    if n == 0 {
        return m;
    }
    if m == 0 {
        return n;
    }

    let mut prev: [Int] = [];
    for j in 0..(m + 1) {
        prev.push(j);
    }

    for i in 1..(n + 1) {
        let mut curr: [Int] = [i];
        for j in 1..(m + 1) {
            let mut cost = 1;
            if s[i - 1] == t[j - 1] {
                cost = 0;
            }

            let mut best = prev[j - 1] + cost;
            if prev[j] + 1 < best {
                best = prev[j] + 1;
            }
            if curr[j - 1] + 1 < best {
                best = curr[j - 1] + 1;
            }
            curr.push(best);
        }
        prev = curr;
    }

    return prev[m];
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        return Stack { items: self.items + [x] }
    }

    fn pop(self) -> Stack {
        if self.items.len() == 0 {
            return self
        }
        return Stack { items: self.items[0..self.items.len() - 1] }
    }

    fn top(self) -> Int? {
        if self.items.len() == 0 {
            return none
        }
        return self.items[self.items.len() - 1]
    }
}

fn median(xs: [Float]) -> Float {
    let mut s = xs
    let n = s.len()

    let mut i = 1
    while i < n {
        let key = s[i]
        let mut j = i
        while j > 0 && s[j - 1] > key {
            s[j] = s[j - 1]
            j = j - 1
        }
        s[j] = key
        i = i + 1
    }

    let mid = n / 2
    if n % 2 == 1 {
        return s[mid]
    }
    return (s[mid - 1] + s[mid]) / 2.0
}

fn pascal(n: Int) -> [Int] {
    let mut row = [1];
    let mut k = 1;
    while k <= n {
        row.push(row[k - 1] * (n - k + 1) / k);
        k = k + 1;
    }
    return row;
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let mut sorted = xs;
    sorted.sort_by(|a, b| a.0 < b.0);

    let mut result: [(Int, Int)] = [];
    for (start, end) in sorted {
        let n = result.len();
        if n > 0 && start <= result[n - 1].1 {
            let last = result[n - 1];
            if end > last.1 {
                result[n - 1] = (last.0, end);
            }
        } else {
            result.push((start, end));
        }
    }
    return result;
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    if len(xs) == 0 {
        return fallback;
    }
    return xs[len(xs) - 1];
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let mut result: [(T, T)] = [];
    let mut i = 0;
    while i + 1 < xs.len() {
        result.push((xs[i], xs[i + 1]));
        i = i + 1;
    }
    return result;
}

