fn sum_squares(lo: Int, hi: Int) -> Int {
    let mut total = 0
    let mut i = lo
    while i <= hi {
        total = total + i * i
        i = i + 1
    }
    total
}

fn squares(n: Int) -> Int ! Error {
    let mid = n / 2
    let first = spawn sum_squares(1, mid)
    let rest = spawn sum_squares(mid + 1, n)
    let a = first.join()?
    let b = rest.join()?
    a + b
}

