        return "0";
    }
    if n == 1 {
        return "1";
    }
    return binary(n / 2) + binary(n % 2);
}

fn mode(xs: [Int]) -> Int {
    let mut best = xs[0];
    let mut bestCount = 0;
    let mut i = 0;
    while i < len(xs) {
        let mut count = 0;
        let mut j = 0;
        while j < len(xs) {
            if xs[j] == xs[i] {
                count = count + 1;
            }
            j = j + 1;
        }
        if count > bestCount || (count == bestCount && xs[i] < best) {
            best = xs[i];
            bestCount = count;
        }
        i = i + 1;
    }
    return best;
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let mut result: [String: Int] = [:]
    let mut i = 0
    while i < keys.len() && i < values.len() {
        result[keys[i]] = values[i]
        i = i + 1
    }
    return result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 || b <= 0 || c <= 0 {
        return "invalid";
    }
    if a - b >= c || b - c >= a || c - a >= b {
        return "invalid";
    }
    if a == b && b == c {
        return "equilateral";
    }
    if a == b || b == c || a == c {
        return "isosceles";
    }
    return "scalene";
}

fn lengths(text: String) -> [Int] {
    let mut result: [Int] = []
    let mut count: Int = 0
    for ch in text {
        if ch == ' ' {
            result.push(count)
            count = 0
        } else {
            count = count + 1
        }
    }
    result.push(count)
    return result
}

fn collatz(n: Int) -> Int {
    if n == 1 {
        return 0;
    }
    if n % 2 == 0 {
        return 1 + collatz(n / 2);
    }
    return 1 + collatz(3 * n + 1);
}

fn sum_digits(text: String) -> Int {
    let mut total: Int = 0;
    for ch in text.chars() {
        if ch >= '0' && ch <= '9' {
            total = total + ((ch as Int) - ('0' as Int));
        }
    }
    return total;
}

fn top(players: [Player], k: Int) -> [String] {
    let mut sorted: [Player] = []
    for p in players {
        let mut i = 0
        while i < sorted.len() && sorted[i].score >= p.score {
            i = i + 1
        }
        sorted.insert(i, p)
    }

    let mut result: [String] = []
    let mut j = 0
    while j < k && j < sorted.len() {
        result.push(sorted[j].name)
        j = j + 1
    }
    return result
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int] {
    let mut out: [Int] = [];
    for x in xs {
        if x < lo {
            out.push(lo);
        } else if x > hi {
            out.push(hi);
        } else {
            out.push(x);
        }
    }
    return out;
}

fn is_sorted(xs: [Int]) -> Bool {
    let mut i = 1;
    while i < len(xs) {
        if xs[i - 1] > xs[i] {
            return false;
        }
        i = i + 1;
    }
    return true;
}

fn digit(n: Int) -> String {
    if n == 0 { return "0"; }
    if n == 1 { return "1"; }
    if n == 2 { return "2"; }
    if n == 3 { return "3"; }
    if n == 4 { return "4"; }
    if n == 5 { return "5"; }
    if n == 6 { return "6"; }
    if n == 7 { return "7"; }
    if n == 8 { return "8"; }
    if n == 9 { return "9"; }
    if n == 10 { return "a"; }
    if n == 11 { return "b"; }
    if n == 12 { return "c"; }
    if n == 13 { return "d"; }
    if n == 14 { return "e"; }
    return "f";
}

fn byte(n: Int) -> String {
    return digit(n / 16) + digit(n % 16);
}

fn hex(r: Int, g: Int, b: Int) -> String {
    return "#" + byte(r) + byte(g) + byte(b);
}

fn simulate(commands: [Int]) -> [Int] {
    let mut queue: [Int] = []
    for c in commands {
        if c > 0 {
            queue.push(c)
        } else if c == 0 && queue.len() > 0 {
            queue.remove(0)
        }
    }
    return queue
}

fn sum_evens(xs: [Int]) -> Int {
    let total = 0
    for x in xs {
        // Int / Int is an Int, so this holds only for even numbers
        if x / 2 * 2 == x {
            total += x
        }
    }
    total
}

fn reverse_words(text: String) -> String {
    let result = ""
    let first = true
    for word in text.replace(" ", "\n").lines() {
        if first {
            result = word
            first = false
        } else {
            result = "{word} {result}"
        }
    }
    result
}

// Uses only the documented text methods: turn every vowel into "a",
// put each "a" on its own line, then count the lines that are exactly "a".
fn count_vowels(text: String) -> Int {
    let marked = text
    for vowel in ["e", "i", "o", "u", "A", "E", "I", "O", "U"] {
        marked = marked.replace(vowel, "a")
    }
    marked = marked.replace("a", "\na\n")

    let count = 0
    for line in marked.lines() {
        if line == "a" {
            count += 1
        }
    }
    count
}

fn fizzbuzz(n: Int) -> String {
    const by_three = n / 3 * 3 == n
    const by_five = n / 5 * 5 == n
    if by_three and by_five {
        "FizzBuzz"
    } else {
        if by_three {
            "Fizz"
        } else {
            if by_five { "Buzz" } else { "{n}" }
        }
    }
}

fn largest(xs: [Int]) -> Int? {
    let best: Int? = none
    for x in xs {
        if x >= (best ?? x) {
            best = x
        }
    }
    best
}

fn word_counts(text: String) -> [String: Int] {
    let counts: [String: Int] = [:]
    for word in text.replace(" ", "\n").lines() {
        if word != "" {
            counts[word] = (counts[word] ?? 0) + 1
        }
    }
    counts
}

fn doubled(text: String) -> Int ! BadInput {
    match Int.parse(text) {
        ok(n) => n * 2
        err(_) => {
            fail NotANumber(text: text)
        }
    }
}

fn factorial(n: Int) -> Int
    require n >= 0 and n <= 20
{
    let acc = 1
    let i = 2
    while i <= n {
        acc = acc * i
        i += 1
    }
    acc
}

fn fib(n: Int) -> Int
    require n >= 0
{
    if n < 2 {
        n
    } else {
        let prev = 0
        let curr = 1
        let i = 1
        while i < n {
            const next = prev + curr
            prev = curr
            curr = next
            i += 1
        }
        curr
    }
}

// Words sorted by length, shortest first; equal lengths keep their order.
fn by_length(words: [String]) -> [String] {
    words.sort_by(w => w.len())
}

fn dedupe(xs: [Int]) -> [Int] {
    let out: [Int] = []
    for x in xs {
        if out.find(y => y == x) == none {
            out.push(x)
        }
    }
    out
}

fn total_area(rects: [Rect]) -> Float {
    let total = 0.0
    for rect in rects {
        total += rect.width * rect.height
    }
    total
}

fn area(s: Shape) -> Float {
    match s {
        Circle(radius) => 3.14 * radius * radius
        Square(side) => side * side
    }
}

fn first_negative(xs: [Int]) -> Int? {
    let found: Int? = none
    let index = 0
    for x in xs {
        if x < 0 {
            found = index
            break
        }
        index += 1
    }
    found
}

fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
{
    const letters = [
        "a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m",
        "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"
    ]

    // Escape "#" so the temporary codes below can never clash with the input.
    let out = text.replace("#", "#!")

    // Phase 1: each lowercase letter becomes a letter-free code "#<index>;".
    let i = 0
    for letter in letters {
        out = out.replace(letter, "#{i};")
        i += 1
    }

    // Phase 2: each code becomes the letter k places further on (wrapping).
    let j = 0
    for letter in letters {
        const source = if j >= k { j - k } else { j - k + 26 }
        out = out.replace("#{source};", letter)
        j += 1
    }

    out.replace("#!", "#")
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let result: [[Int]] = []
    let j = 0
    for _ in m[0] {
        let column: [Int] = []
        for row in m {
            column.push(row[j])
        }
        result.push(column)
        j += 1
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let result: Int? = none
    let i = 0
    for x in xs {
        if x >= target {
            if x == target {
                result = i
            }
            break
        }
        i += 1
    }
    result
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail DivideByZero
    }
    a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let groups: [String: [String]] = [:]
    for word in words {
        const letter = word.slice(0, 1)
        const existing = groups[letter] ?? []
        groups[letter] = existing + [word]
    }
    groups
}

fn running(xs: [Int]) -> [Int] {
    let out: [Int] = []
    let total = 0
    for x in xs {
        total += x
        out.push(total)
    }
    out
}

fn gcd(a: Int, b: Int) -> Int {
    let x = a
    let y = b
    while y != 0 {
        // remainder of x divided by y, using integer division
        const r = x - (x / y) * y
        x = y
        y = r
    }
    x
}

fn is_prime(n: Int) -> Bool {
    if n < 2 {
        false
    } else if n < 4 {
        true
    } else if n / 2 * 2 == n {
        false
    } else {
        let i = 3
        let prime = true
        while prime and i <= n / i {
            if n / i * i == n {
                prime = false
            }
            i += 2
        }
        prime
    }
}

fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    let candidate = 2
    while candidate < n {
        let is_prime = true
        let d = 2
        while is_prime and d * d <= candidate {
            if candidate % d == 0 {
                is_prime = false
            }
            d += 1
        }
        if is_prime {
            primes.push(candidate)
        }
        candidate += 1
    }
    primes
}

fn digit_sum(n: Int) -> Int
    require n >= 0
{
    let rest = n
    let total = 0
    while rest > 0 {
        const quotient = rest / 10
        total += rest - quotient * 10
        rest = quotient
    }
    total
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let count = 0
    for ch in text.chars() {
        const piece = "{ch}"
        if piece == current {
            count += 1
        } else {
            if count > 0 {
                result = "{result}{current}{count}"
            }
            current = piece
            count = 1
        }
    }
    if count > 0 {
        result = "{result}{current}{count}"
    }
    result
}

fn balanced(text: String) -> Bool {
    const open_brace = "\{"
    const close_brace = r"}"
    const brackets = ["(", ")", "[", "]", open_brace, close_brace]

    // Put every bracket on a line of its own.
    let spaced = text
    for bracket in brackets {
        spaced = spaced.replace(bracket, "\n{bracket}\n")
    }

    // Keep only the bracket lines; everything else is ignored.
    let kept = ""
    for line in spaced.lines() {
        for bracket in brackets {
            if line == bracket {
                kept = "{kept}{line}"
            }
        }
    }

    // Repeatedly delete adjacent matching pairs until nothing changes.
    const braces = "{open_brace}{close_brace}"
    let changed = true
    while changed {
        const next = kept
            .replace("()", "")
            .replace("[]", "")
            .replace(braces, "")
        changed = not (next == kept)
        kept = next
    }

    kept == ""
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let result: (Int, Int)? = none
    let found = false
    let i = 0
    for a in xs {
        if not found {
            let j = 0
            for b in xs {
                if not found and j > i and a + b == target {
                    result = (i, j)
                    found = true
                }
                j += 1
            }
        }
        i += 1
    }
    result
}

