// Strips every letter except `letter`, leaving a run whose size is that letter's count.
fn keep_only(text: String, letter: String, letters: [String]) -> String {
    let kept = text
    for other in letters {
        if not (other == letter) {
            kept = kept.replace(other, "")
        }
    }
    kept
}

fn anagrams(a: String, b: String) -> Bool {
    const letters = [
        "a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m",
        "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"
    ]
    const x = lowered(a)
    const y = lowered(b)
    let same = true
    for letter in letters {
        if not (keep_only(x, letter, letters) == keep_only(y, letter, letters)) {
            same = false
        }
    }
    same
}

fn digit(d: Int, one: String, five: String, ten: String) -> String {
    if d == 1 {
        one
    } else if d == 2 {
        "{one}{one}"
    } else if d == 3 {
        "{one}{one}{one}"
    } else if d == 4 {
        "{one}{five}"
    } else if d == 5 {
        five
    } else if d == 6 {
        "{five}{one}"
    } else if d == 7 {
        "{five}{one}{one}"
    } else if d == 8 {
        "{five}{one}{one}{one}"
    } else if d == 9 {
        "{one}{ten}"
    } else {
        ""
    }
}

fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
{
    const thousands = digit(n / 1000, "M", "", "")
    const hundreds = digit(n / 100 % 10, "C", "D", "M")
    const tens = digit(n / 10 % 10, "X", "L", "C")
    const ones = digit(n % 10, "I", "V", "X")
    "{thousands}{hundreds}{tens}{ones}"
}

fn flatten(xss: [[Int]]) -> [Int] {
    let result: [Int] = []
    for xs in xss {
        for x in xs {
            result.push(x)
        }
    }
    result
}

fn chunks(xs: [Int], n: Int) -> [[Int]]
    require n >= 1
{
    let result: [[Int]] = []
    let current: [Int] = []
    let size = 0
    for x in xs {
        current.push(x)
        size += 1
        if size == n {
            result.push(current)
            current = []
            size = 0
        }
    }
    if size > 0 {
        result.push(current)
    }
    result
}

fn rotate(xs: [Int], k: Int) -> [Int]
    require k >= 0
{
    let n = 0
    for x in xs {
        n += 1
    }
    if n == 0 {
        xs
    } else {
        // k modulo n, so k may be larger than the list
        const r = k - (k / n) * n
        xs.skip(r) + xs.take(r)
    }
}

fn shared_prefix(a: String, b: String) -> String {
    const limit = if a.len() < b.len() { a.len() } else { b.len() }
    let n = 0
    while n < limit and a.slice(n, n + 1) == b.slice(n, n + 1) {
        n += 1
    }
    a.slice(0, n)
}

fn common_prefix(words: [String]) -> String {
    let prefix = ""
    let started = false
    for word in words {
        if not started {
            prefix = word
            started = true
        } else {
            prefix = shared_prefix(prefix, word)
        }
    }
    prefix
}

fn second_largest(xs: [Int]) -> Int? {
    let largest: Int? = none
    let second: Int? = none
    for x in xs {
        if let top = largest {
            if x > top {
                second = largest
                largest = x
            } else if x < top {
                if let s = second {
                    if x > s {
                        second = x
                    }
                } else {
                    second = x
                }
            }
        } else {
            largest = x
        }
    }
    second
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    let result: [Int] = []
    let i = 0
    let j = 0
    while i < a.len() and j < b.len() {
        if a[i] <= b[j] {
            result.push(a[i])
            i += 1
        } else {
            result.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        result.push(a[i])
        i += 1
    }
    while j < b.len() {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const chars_a = a.chars()
    const chars_b = b.chars()
    const width = chars_b.len()

    let prev = [0]
    for j in 0..width {
        prev.push(j + 1)
    }

    let row = 0
    for ca in chars_a {
        row += 1
        let cur = [row]
        let j = 0
        for cb in chars_b {
            const cost = if ca == cb { 0 } else { 1 }
            let best = prev[j] + cost
            const deletion = prev[j + 1] + 1
            if deletion < best {
                best = deletion
            }
            const insertion = cur[j] + 1
            if insertion < best {
                best = insertion
            }
            cur.push(best)
            j += 1
        }
        prev = cur
    }

    prev[width]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        Stack(items: self.items + [x])
    }

    fn pop(self) -> Stack {
        let size = 0
        for item in self.items {
            size += 1
        }
        if size == 0 {
            self
        } else {
            Stack(items: self.items.take(size - 1))
        }
    }

    fn top(self) -> Int? {
        let result: Int? = none
        for item in self.items {
            result = item
        }
        result
    }
}

fn count_char(text: String, c: Char) -> Int {
    let total = 0
    for ch in text.chars() {
        if ch == c {
            total += 1
        }
    }
    total
}

// Median of a non-empty list: the middle value when sorted,
// or the mean of the two middle values for an even count.
fn median(xs: [Float]) -> Float {
    const sorted = xs.sort()

    let n = 0
    for x in sorted {
        n += 1
    }
    const mid = n / 2

    let lower: Float = 0.0
    let upper: Float = 0.0
    let i = 0
    for x in sorted {
        if i == mid - 1 {
            lower = x
        }
        if i == mid {
            upper = x
        }
        i += 1
    }

    if mid * 2 == n { (lower + upper) / 2.0 } else { upper }
}

fn pascal(n: Int) -> [Int]
    require n >= 0
{
    let row = [1]
    let value = 1
    const end = n + 1
    for k in 1..end {
        value = value * (n - k + 1) / k
        row.push(value)
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort()
    let merged: [(Int, Int)] = []
    let started = false
    let cur_lo = 0
    let cur_hi = 0
    for (lo, hi) in sorted {
        if started and lo <= cur_hi {
            if hi > cur_hi {
                cur_hi = hi
            }
        } else {
            if started {
                merged.push((cur_lo, cur_hi))
            }
            cur_lo = lo
            cur_hi = hi
            started = true
        }
    }
    if started {
        merged.push((cur_lo, cur_hi))
    }
    merged
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    let result = fallback
    for x in xs {
        result = x
    }
    result
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let out: [(T, T)] = []
    let prev: T? = none
    for x in xs {
        if let p = prev {
            out.push((p, x))
        }
        prev = x
    }
    out
}

fn names(xs: [Named]) -> String {
    let result = ""
    let first = true
    for x in xs {
        if first {
            result = x.name()
            first = false
        } else {
            result = "{result}, {x.name()}"
        }
    }
    result
}

fn message(e: LoginError) -> String {
    match e {
        NoSuchUser(name) => "no user {name}"
        WrongPassword => "wrong password"
        Locked(minutes) => "locked for {minutes} minutes"
    }
}

fn port_sum(text: String) -> Int ! PortError {
    if text.replace(":", "") == text {
        fail PortError.Bad(text: text)
    }
    let total = 0
    let parts = 0
    for part in text.replace(":", "\n").lines() {
        total += try parse_port(part)
        parts += 1
    }
    if parts != 2 {
        fail PortError.Bad(text: text)
    }
    total
}

// Note: the Kavach guide does not cover concurrency, so `spawn` and
// `.join()` below are assumed syntax. Check docs/spec/ for the real task API.

fn sum_squares(from: Int, to: Int) -> Int {
    let total = 0
    let i = from
    while i <= to {
        total += i * i
        i += 1
    }
    total
}

fn squares(n: Int) -> Int ! Error {
    const mid = n / 2
    const first = spawn sum_squares(1, mid)
    const second = spawn sum_squares(mid + 1, n)
    const a = try first.join()
    const b = try second.join()
    a + b
}

fn total_qty(text: String) -> Int {
    match json.decode<[Item]>(text) {
        ok(items) => items.sum(.qty)
        err(_) => -1
    }
}

fn total(items: [(Decimal, Int)]) -> Decimal {
    let running: Decimal = 0
    for (price, quantity) in items {
        running += price * Decimal(quantity)
    }
    running
}

fn deposit(a: Account, amount: Int) -> Account {
    a with { balance: a.balance + amount }
}

fn swap_ends(inout xs: [Int]) {
    // Walk the list once to learn its length and its last item.
    let n = 0
    let last = 0
    for x in xs {
        last = x
        n += 1
    }
    if n >= 2 {
        xs[n - 1] = xs[0]
        xs[0] = last
    }
}

fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    let keys: [String] = []
    for (key, value) in m {
        if value >= min {
            keys.push(key)
        }
    }
    keys.sort()
}

fn numbered(items: [String]) -> String {
    let result = ""
    let index = 0
    for item in items {
        index += 1
        if index == 1 {
            result = "{index}. {item}"
        } else {
            result = "{result}\n{index}. {item}"
        }
    }
    result
}

fn add_or_none(a: Int, b: Int) -> Int? {
    const max = 9_223_372_036_854_775_807
    const min = -max - 1
    if (b > 0 and a > max - b) or (b < 0 and a < min - b) {
        none
    } else {
        a + b
    }
}

fn adder(step: Int) -> fn(Int) -> Int {
    x => x + step
}

fn key_count(events: [Event]) -> Int {
    let total = 0
    for event in events {
        total += match event {
            Key(_) => 1
            Click => 0
            Scroll(_) => 0
        }
    }
    total
}

fn csv(n: Int) -> String {
    let text = ""
    let i = 1
    while i <= n {
        if i > 1 {
            text = "{text},"
        }
        text = "{text}{i}"
        i += 1
    }
    text
}

fn is_power_of_two(n: Int) -> Bool {
    if n <= 0 {
        false
    } else {
        let x = n
        while x / 2 * 2 == x {
            x = x / 2
        }
        x == 1
    }
}

fn binary(n: Int) -> String
    require n >= 0
{
    let rest = n
    let out = ""
    while rest > 0 {
        const half = rest / 2
        const bit = rest - half * 2
        out = "{bit}{out}"
        rest = half
    }
    if n == 0 { "0" } else { out }
}

fn mode(xs: [Int]) -> Int {
    let best = 0
    let best_count = 0
    for x in xs {
        let c = 0
        for y in xs {
            if y == x {
                c += 1
            }
        }
        if c > best_count or (c == best_count and x < best) {
            best = x
            best_count = c
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let result: [String: Int] = [:]
    let i = 0
    for key in keys {
        // Yields the value at position i, or nothing once values runs out.
        for value in values.skip(i).take(1) {
            result[key] = value
        }
        i += 1
    }
    result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 or b <= 0 or c <= 0 {
        "invalid"
    } else if a - b >= c or b - c >= a or c - a >= b {
        "invalid"
    } else if a == b and b == c {
        "equilateral"
    } else if a == b or b == c or a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

fn lengths(text: String) -> [Int] {
    text.split(" ")
        .filter(word => word != "")
        .map(word => word.len())
}

fn collatz(n: Int) -> Int
    require n >= 1
{
    let current = n
    let steps = 0
    while current != 1 {
        const half = current / 2
        if half * 2 == current {
            current = half
        } else {
            current = 3 * current + 1
        }
        steps += 1
    }
    steps
}

fn sum_digits(text: String) -> Int {
    // Remove existing line breaks so that only the ones we insert are counted.
    const flat = text.replace("\n", " ").replace("\r", " ")
    // Pad both ends so a digit at the edge still splits into two pieces.
    const padded = "x{flat}x"
    let total = 0
    for d in [1, 2, 3, 4, 5, 6, 7, 8, 9] {
        let pieces = 0
        for _ in padded.replace("{d}", "\n").lines() {
            pieces += 1
        }
        // N occurrences of the digit split the text into N + 1 pieces.
        total += d * (pieces - 1)
    }
    total
}

fn top(players: [Player], k: Int) -> [String] {
    players
        .sort_by(p => -p.score)
        .take(k)
        .map(.name)
}

fn clamp_one(x: Int, lo: Int, hi: Int) -> Int {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int]
    require lo <= hi
{
    xs.map(x => clamp_one(x, lo, hi))
}

fn is_sorted(xs: [Int]) -> Bool {
    let sorted = true
    let first = true
    let prev = 0
    for x in xs {
        if not first and x < prev {
            sorted = false
        }
        first = false
        prev = x
    }
    sorted
}

fn hex_digit(n: Int) -> String {
    let d = "{n}"
    if n == 10 { d = "a" }
    if n == 11 { d = "b" }
    if n == 12 { d = "c" }
    if n == 13 { d = "d" }
    if n == 14 { d = "e" }
    if n == 15 { d = "f" }
    d
}

fn hex_pair(n: Int) -> String {
    const high = n / 16
    const low = n - high * 16
    const a = hex_digit(high)
    const b = hex_digit(low)
    "{a}{b}"
}

fn hex(r: Int, g: Int, b: Int) -> String {
    const rr = hex_pair(r)
    const gg = hex_pair(g)
    const bb = hex_pair(b)
    "#{rr}{gg}{bb}"
}

fn simulate(commands: [Int]) -> [Int] {
    let joined = 0
    let removed = 0
    for command in commands {
        if command > 0 {
            joined += 1
        }
        if command == 0 and removed < joined {
            removed += 1
        }
    }
    commands.filter(c => c > 0).skip(removed)
}

fn sum_evens(xs: [Int]) -> Int {
    let total = 0
    for x in xs {
        // x is even exactly when halving and doubling gives x back
        if x / 2 * 2 == x {
            total += x
        }
    }
    total
}

fn reverse_words(text: String) -> String {
    let result = ""
    let first = true
    for word in text.replace(" ", "\n").lines() {
        if first {
            result = word
            first = false
        } else {
            result = "{word} {result}"
        }
    }
    result
}

fn count_vowels(text: String) -> Int {
    // Pad both ends so the text never starts or ends with a line break,
    // neutralise existing line breaks, then turn every vowel into one.
    // The number of lines is then the number of vowels plus one.
    const padded = "x{text}x"
    const marked = padded
        .replace("\n", " ")
        .replace("a", "\n")
        .replace("e", "\n")
        .replace("i", "\n")
        .replace("o", "\n")
        .replace("u", "\n")
        .replace("A", "\n")
        .replace("E", "\n")
        .replace("I", "\n")
        .replace("O", "\n")
        .replace("U", "\n")
    let pieces = 0
    for _piece in marked.lines() {
        pieces += 1
    }
    pieces - 1
}

fn fizzbuzz(n: Int) -> String {
    // Int / Int is an Int, so n is a multiple of k exactly when n / k * k == n
    const by_three = n / 3 * 3 == n
    const by_five = n / 5 * 5 == n
    if by_three and by_five {
        "FizzBuzz"
    } else if by_three {
        "Fizz"
    } else if by_five {
        "Buzz"
    } else {
        "{n}"
    }
}

fn largest(xs: [Int]) -> Int? {
    let best: Int? = none
    for x in xs {
        const current = best ?? x
        best = if x > current { x } else { current }
    }
    best
}

fn word_counts(text: String) -> [String: Int] {
    let counts: [String: Int] = [:]
    for word in text.replace(" ", "\n").lines() {
        if word != "" {
            counts[word] = (counts[word] ?? 0) + 1
        }
    }
    counts
}

fn doubled(text: String) -> Int ! BadInput {
    match Int(text) {
        ok(n) => n * 2
        err(_) => {
            fail BadInput.NotANumber(text: text)
        }
    }
}

fn factorial(n: Int) -> Int
    require n >= 0 and n <= 20
{
    if n <= 1 { 1 } else { n * factorial(n - 1) }
}

fn fib(n: Int) -> Int
    require n >= 0
{
    if n == 0 {
        0
    } else {
        let prev = 0
        let curr = 1
        let i = 1
        while i < n {
            const next = prev + curr
            prev = curr
            curr = next
            i += 1
        }
        curr
    }
}

fn by_length(words: [String]) -> [String] {
    words.sort_by(w => w.len())
}

fn dedupe(xs: [Int]) -> [Int] {
    let result: [Int] = []
    for x in xs {
        let is_new = true
        for y in result {
            if y == x {
                is_new = false
            }
        }
        if is_new {
            result.push(x)
        }
    }
    result
}

fn total_area(rects: [Rect]) -> Float {
    let total: Float = 0.0
    for rect in rects {
        total += rect.width * rect.height
    }
    total
}

fn area(s: Shape) -> Float {
    match s {
        Shape.Circle(radius) => 3.14 * radius * radius
        Shape.Square(side) => side * side
    }
}

fn first_negative(xs: [Int]) -> Int? {
    let found: Int? = none
    let i = 0
    for x in xs {
        if x < 0 {
            found = i
            break
        }
        i += 1
    }
    found
}

fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
{
    const letters = [
        "a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m",
        "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"
    ]

    // Escape the marker so an original "~" can never look like a token.
    let out = text.replace("~", "~!")

    // Pass 1: turn every lowercase letter into a letter-free token "~<index>.".
    let i = 0
    for letter in letters {
        out = out.replace(letter, "~{i}.")
        i += 1
    }

    // Pass 2: turn each token into the letter k places further on (wrapping).
    let j = 0
    for letter in letters {
        const source = if j - k < 0 { j - k + 26 } else { j - k }
        out = out.replace("~{source}.", letter)
        j += 1
    }

    // Undo the escape.
    out.replace("~!", "~")
}

fn transpose(m: [[Int]]) -> [[Int]] {
    let result: [[Int]] = []
    let j = 0
    for _ in m[0] {
        let column: [Int] = []
        for row in m {
            column.push(row[j])
        }
        result.push(column)
        j += 1
    }
    result
}

// Scans the sorted list in order and stops as soon as values pass the target.
fn find(xs: [Int], target: Int) -> Int? {
    let found: Int? = none
    let i = 0
    for x in xs {
        if x >= target {
            if x == target {
                found = i
            }
            break
        }
        i += 1
    }
    found
}

fn divide(a: Int, b: Int) -> Int ! MathError {
    if b == 0 {
        fail MathError.DivideByZero
    }
    a / b
}

fn by_letter(words: [String]) -> [String: [String]] {
    let groups: [String: [String]] = [:]
    for word in words {
        const letter = word.slice(0, 1)
        let existing: [String] = groups[letter] ?? []
        existing.push(word)
        groups[letter] = existing
    }
    groups
}

fn running(xs: [Int]) -> [Int] {
    let out: [Int] = []
    let total = 0
    for x in xs {
        total += x
        out.push(total)
    }
    out
}

fn gcd(a: Int, b: Int) -> Int
    require a > 0 and b > 0
{
    let x = a
    let y = b
    while y != 0 {
        const remainder = x - (x / y) * y
        x = y
        y = remainder
    }
    x
}

fn is_prime(n: Int) -> Bool {
    let result = n >= 2
    let i = 2
    while result and i <= n / i {
        if n / i * i == n {
            result = false
        }
        i += 1
    }
    result
}

fn primes_below(n: Int) -> [Int] {
    let primes: [Int] = []
    let candidate = 2
    while candidate < n {
        let is_prime = true
        let d = 2
        while is_prime and d * d <= candidate {
            if candidate % d == 0 {
                is_prime = false
            }
            d += 1
        }
        if is_prime {
            primes.push(candidate)
        }
        candidate += 1
    }
    primes
}

fn digit_sum(n: Int) -> Int
    require n >= 0
{
    let remaining = n
    let total = 0
    while remaining > 0 {
        const quotient = remaining / 10
        total += remaining - quotient * 10
        remaining = quotient
    }
    total
}

fn rle(text: String) -> String {
    let result = ""
    let current = ""
    let count = 0
    let i = 0
    // Walk the text one character at a time; stop once the prefix is the whole text.
    while text.slice(0, i) != text {
        const c = text.slice(i, i + 1)
        if count > 0 and c == current {
            count += 1
        } else {
            if count > 0 {
                result = "{result}{current}{count}"
            }
            current = c
            count = 1
        }
        i += 1
    }
    if count > 0 {
        result = "{result}{current}{count}"
    }
    result
}

// Only documented text operations are used: put every bracket on its own
// line, keep just those lines, then delete adjacent pairs until nothing changes.

fn is_bracket(piece: String) -> Bool {
    piece == "(" or piece == ")" or piece == "[" or piece == "]" or piece == "\{" or piece == "}"
}

fn remove_pairs(brackets: String) -> String {
    brackets.replace("()", "").replace("[]", "").replace("\{}", "")
}

fn balanced(text: String) -> Bool {
    const spaced = text
        .replace("(", "\n(\n")
        .replace(")", "\n)\n")
        .replace("[", "\n[\n")
        .replace("]", "\n]\n")
        .replace("\{", "\n\{\n")
        .replace("}", "\n}\n")

    let current = ""
    for piece in spaced.lines() {
        if is_bracket(piece) {
            current = "{current}{piece}"
        }
    }

    let done = false
    while not done {
        const next = remove_pairs(current)
        done = next == current
        current = next
    }
    current == ""
}

fn two_sum(xs: [Int], target: Int) -> (Int, Int)? {
    let result: (Int, Int)? = none
    let found = false
    let i = 0
    for x in xs {
        if not found {
            let j = 0
            for y in xs {
                if not found and j > i and x + y == target {
                    result = (i, j)
                    found = true
                }
                j += 1
            }
        }
        i += 1
    }
    result
}

fn lower(text: String) -> String {
    text
        .replace("A", "a")
        .replace("B", "b")
        .replace("C", "c")
        .replace("D", "d")
        .replace("E", "e")
        .replace("F", "f")
        .replace("G", "g")
        .replace("H", "h")
        .replace("I", "i")
        .replace("J", "j")
        .replace("K", "k")
        .replace("L", "l")
        .replace("M", "m")
        .replace("N", "n")
        .replace("O", "o")
        .replace("P", "p")
        .replace("Q", "q")
        .replace("R", "r")
        .replace("S", "s")
        .replace("T", "t")
        .replace("U", "u")
        .replace("V", "v")
        .replace("W", "w")
        .replace("X", "x")
        .replace("Y", "y")
        .replace("Z", "z")
}

fn letters() -> [String] {
    ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m",
        "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"]
}

// Removes every letter except `keep`, so what is left shows how many
// times `keep` occurs.
fn only(text: String, keep: String) -> String {
    let out = text
    for letter in letters() {
        out = if letter == keep { out } else { out.replace(letter, "") }
    }
    out
}

fn anagrams(a: String, b: String) -> Bool {
    const x = lower(a)
    const y = lower(b)
    let same = true
    for letter in letters() {
        same = same and (only(x, letter) == only(y, letter))
    }
    same
}

fn roman(n: Int) -> String
    require n >= 1 and n <= 3999
{
    const table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    let remaining = n
    let result = ""
    for (value, symbol) in table {
        while remaining >= value {
            result = "{result}{symbol}"
            remaining = remaining - value
        }
    }
    result
}

fn flatten(xss: [[Int]]) -> [Int] {
    let result: [Int] = []
    for xs in xss {
        for x in xs {
            result.push(x)
        }
    }
    result
}

fn chunks(xs: [Int], n: Int) -> [[Int]]
    require n >= 1
{
    let result: [[Int]] = []
    let current: [Int] = []
    let size = 0
    for x in xs {
        current.push(x)
        size += 1
        if size == n {
            result.push(current)
            current = []
            size = 0
        }
    }
    if size > 0 {
        result.push(current)
    }
    result
}

fn rotate(xs: [Int], k: Int) -> [Int]
    require k >= 0
{
    let n = 0
    for _ in xs {
        n += 1
    }
    if n == 0 {
        xs
    } else {
        const shift = k - (k / n) * n
        let all = xs.skip(shift)
        for x in xs.take(shift) {
            all.push(x)
        }
        all
    }
}

fn shared_prefix(a: String, b: String) -> String {
    const limit = if a.len() < b.len() { a.len() } else { b.len() }
    let n = 0
    while n < limit and a.slice(n, n + 1) == b.slice(n, n + 1) {
        n += 1
    }
    a.slice(0, n)
}

fn common_prefix(words: [String]) -> String {
    let prefix = ""
    let started = false
    for word in words {
        if not started {
            prefix = word
            started = true
        } else {
            prefix = shared_prefix(prefix, word)
        }
    }
    prefix
}

fn second_largest(xs: [Int]) -> Int? {
    let have_top = false
    let have_second = false
    let top = 0
    let second = 0
    for x in xs {
        if not have_top {
            top = x
            have_top = true
        } else if x > top {
            second = top
            have_second = true
            top = x
        } else if x < top {
            if not have_second {
                second = x
                have_second = true
            } else if x > second {
                second = x
            }
        }
    }
    let result: Int? = none
    if have_second {
        result = second
    }
    result
}

fn merge(a: [Int], b: [Int]) -> [Int] {
    // Count b's length with a loop so only documented features are needed.
    let b_len = 0
    for _ in b {
        b_len += 1
    }

    let result: [Int] = []
    let j = 0
    for x in a {
        while j < b_len {
            if b[j] >= x {
                break
            }
            result.push(b[j])
            j += 1
        }
        result.push(x)
    }
    while j < b_len {
        result.push(b[j])
        j += 1
    }
    result
}

fn distance(a: String, b: String) -> Int {
    const b_chars = b.chars()

    // Row for the empty prefix of `a`: distance to each prefix of `b`.
    let prev: [Int] = [0]
    let width = 0
    for _ in b_chars {
        width += 1
        prev.push(width)
    }

    let row = 0
    for ca in a.chars() {
        row += 1
        let current: [Int] = [row]
        let j = 0
        for cb in b_chars {
            const cost = if ca == cb { 0 } else { 1 }
            let best = prev[j] + cost
            const deletion = prev[j + 1] + 1
            if deletion < best {
                best = deletion
            }
            const insertion = current[j] + 1
            if insertion < best {
                best = insertion
            }
            current.push(best)
            j += 1
        }
        prev = current
    }

    prev[width]
}

type Stack {
    items: [Int]

    fn push(self, x: Int) -> Stack {
        let all = self.items
        all.push(x)
        Stack(items: all)
    }

    fn pop(self) -> Stack {
        let n = 0
        for _item in self.items {
            n += 1
        }
        if n == 0 {
            self
        } else {
            Stack(items: self.items.take(n - 1))
        }
    }

    fn top(self) -> Int? {
        let last: Int? = none
        for item in self.items {
            last = item
        }
        last
    }
}

fn count_char(text: String, c: Char) -> Int {
    let total = 0
    for ch in text.chars() {
        if ch == c {
            total += 1
        }
    }
    total
}

// Median of a non-empty list: the middle value when sorted,
// or the mean of the two middle values for an even count.
fn median(xs: [Float]) -> Float {
    const sorted = xs.sort()

    let n = 0
    for _ in sorted {
        n += 1
    }

    const mid = n / 2
    let lower: Float = 0.0
    let upper: Float = 0.0
    let i = 0
    for x in sorted {
        if i == mid - 1 {
            lower = x
        }
        if i == mid {
            upper = x
        }
        i += 1
    }

    if mid * 2 == n {
        (lower + upper) / 2.0
    } else {
        upper
    }
}

fn pascal(n: Int) -> [Int]
    require n >= 0
{
    let row = [1]
    for k in 0..n {
        row.push(row[k] * (n - k) / (k + 1))
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    let merged: [(Int, Int)] = []
    let started = false
    let cur_lo = 0
    let cur_hi = 0
    for (lo, hi) in xs.sort() {
        if not started {
            cur_lo = lo
            cur_hi = hi
            started = true
        } else if lo <= cur_hi {
            if hi > cur_hi {
                cur_hi = hi
            }
        } else {
            merged.push((cur_lo, cur_hi))
            cur_lo = lo
            cur_hi = hi
        }
    }
    if started {
        merged.push((cur_lo, cur_hi))
    }
    merged
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    let result = fallback
    for x in xs {
        result = x
    }
    result
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let paired: [(T, T)] = []
    let prev: T? = none
    for x in xs {
        if let p = prev {
            paired.push((p, x))
        }
        prev = x
    }
    paired
}

fn names(xs: [Named]) -> String {
    let out = ""
    let first = true
    for x in xs {
        const n = x.name()
        if first {
            out = n
            first = false
        } else {
            out = "{out}, {n}"
        }
    }
    out
}

fn message(e: LoginError) -> String {
    match e {
        LoginError.NoSuchUser(name) => "no user {name}"
        LoginError.WrongPassword => "wrong password"
        LoginError.Locked(minutes) => "locked for {minutes} minutes"
    }
}

fn port_sum(text: String) -> Int ! PortError {
    // Removing ":" changes nothing only when there is no colon at all.
    if text.replace(":", "") == text {
        fail PortError.Bad(text: text)
    }
    let total = 0
    let seen = 0
    for part in text.replace(":", "\n").lines() {
        const port = try parse_port(part)
        total += port
        seen += 1
    }
    if seen < 2 {
        // One side of the colon was empty (e.g. "80:"), so pass on that failure.
        const missing = try parse_port("")
        total += missing
    }
    total
}

fn sum_squares(from: Int, to: Int) -> Int {
    let total = 0
    let i = from
    while i <= to {
        total += i * i
        i += 1
    }
    total
}

fn squares(n: Int) -> Int ! Error {
    const mid = n / 2
    const first = spawn { sum_squares(1, mid) }
    const rest = spawn { sum_squares(mid + 1, n) }
    const a = try first.wait()
    const b = try rest.wait()
    a + b
}

