fn add_or_none(a: Int, b: Int) -> Int? {
    const int_max: Int = 9_223_372_036_854_775_807
    const int_min: Int = -int_max - 1
    const overflows = (b > 0 and a > int_max - b) or (b < 0 and a < int_min - b)
    if overflows {
        none
    } else {
        a + b
    }
}

fn adder(step: Int) -> fn(Int) -> Int {
