}

fn clamp_one(x: Int, lo: Int, hi: Int) -> Int {
    if x < lo {
        lo
    } else {
        if x > hi { hi } else { x }
    }
}

fn clamp_all(xs: [Int], lo: Int, hi: Int) -> [Int]
    require lo <= hi
{
