}

fn is_sorted(xs: [Int]) -> Bool {
    let sorted = true
    let first = true
    let prev = 0
    for x in xs {
        if not first and x < prev {
            sorted = false
        }
        first = false
        prev = x
    }
    sorted
}

fn hex_digit(n: Int) -> String {
    if n < 10 {
        "{n}"
    } else if n == 10 {
        "a"
    } else if n == 11 {
        "b"
    } else if n == 12 {
        "c"
    } else if n == 13 {
        "d"
    } else if n == 14 {
        "e"
    } else {
