    const blue = hex_byte(b)
    "#{red}{green}{blue}"
}

fn simulate(commands: [Int]) -> [Int] {
    let size = 0
    let removed = 0
    for command in commands {
        if command > 0 {
            size += 1
        }
        if command == 0 and size > 0 {
            size -= 1
            removed += 1
        }
    }
    commands.filter(c => c > 0).skip(removed)
}

fn sum_evens(xs: [Int]) -> Int
