    example sum_evens([]) == 0
    example sum_evens([-2, -3, 7]) == -2
{
    let total = 0
    for x in xs {
        if x % 2 == 0 {
            // wrapping keeps the result exact whenever the true sum fits in Int,
            // even if a partial sum briefly goes out of range
            total = total.wrapping_add(x)
        }
    }
    total
}

fn reverse_words(text: String) -> String {
