fn caesar(text: String, k: Int) -> String
    require k >= 0 and k <= 25
    example caesar("abc xyz!", 3) == "def abc!"
{
    const alphabet = "abcdefghijklmnopqrstuvwxyz"
    let out = ""
    for ch in text.chars() {
        const s = "{ch}"
        let found = -1
        for i in 0..26 {
            if alphabet.slice(i, i + 1) == s {
                found = i
            }
        }
        if found >= 0 {
            const j = (found + k) % 26
            out += alphabet.slice(j, j + 1)
        } else {
            out += s
        }
    }
    out
}

fn transpose(m: [[Int]]) -> [[Int]]
