    for j in 0..m[0].len() {
        let row: [Int] = []
        for i in 0..m.len() {
            row.push(m[i][j])
        }
        result.push(row)
    }
    result
}

fn find(xs: [Int], target: Int) -> Int? {
    let lo = 0
    let hi = xs.len()
    while lo < hi {
        const mid = lo + (hi - lo) / 2
        const value = xs[mid]
        if value == target {
            return mid
        }
        if value < target {
            lo = mid + 1
        } else {
            hi = mid
        }
    }
    none
}

