fn median(xs: [Float]) -> Float
    require xs.len() > 0
    example median([3.0, 1.0, 2.0]) == 2.0
    example median([4.0, 1.0, 3.0, 2.0]) == 2.5
{
    const sorted = xs.sort()
    const n = sorted.len()
    const mid = n / 2
    if n % 2 != 0 {
        sorted[mid]
    } else {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    }
}

fn pascal(n: Int) -> [Int]
    require n >= 0
    require n <= 66
    ensure result.len() == n + 1
    example pascal(0) == [1]
    example pascal(4) == [1, 4, 6, 4, 1]
{
    let row = [1]
    for i in 0..n {
        let next = [1]
        for j in 1..(i + 1) {
            next.push(row[j - 1] + row[j])
        }
        next.push(1)
        row = next
    }
    row
}

fn merge_intervals(xs: [(Int, Int)]) -> [(Int, Int)] {
    const sorted = xs.sort_by(.0)
    let out: [(Int, Int)] = []
    let has = false
    let cur_start = 0
    let cur_end = 0
    for (s, e) in sorted {
        if not has {
            cur_start = s
            cur_end = e
            has = true
        } else if s <= cur_end {
            if e > cur_end {
                cur_end = e
            }
        } else {
            out.push((cur_start, cur_end))
            cur_start = s
            cur_end = e
        }
    }
    if has {
        out.push((cur_start, cur_end))
    }
    out
}

fn last_or<T>(xs: [T], fallback: T) -> T {
    xs.last() ?? fallback
}

fn pairs<T>(xs: [T]) -> [(T, T)] {
    let out: [(T, T)] = []
    if xs.len() < 2 {
        return out
    }
    for i in 0..xs.len() - 1 {
        out.push((xs[i], xs[i + 1]))
    }
    out
}

fn names(xs: [Named]) -> String {
    xs.map(x => x.name()).join(", ")
}

fn percent(part: Int, whole: Int) -> Int
    require whole > 0
    require part >= 0 and part <= whole
    ensure result >= 0 and result <= 100
    example percent(1, 3) == 33
    example percent(0, 5) == 0
    example percent(5, 5) == 100
    example percent(2, 3) == 66
    example percent(92233720368547759, 92233725446742979) == 99
    example percent(9223372036854775806, 9223372036854775807) == 99
    example percent(4611686018427387904, 9223372036854775807) == 50
{
    if part == whole {
        100
    } else {
        // Builds part * 100 / whole one binary digit of 100 at a time,
        // keeping quotient * whole + rest == part * k with rest < whole,
        // so no step can overflow however large the inputs are.
        let quotient = 0
        let rest = part
        for bit in [1, 0, 0, 1, 0, 0] {
            if rest >= whole - rest {
                rest = rest - (whole - rest)
                quotient = quotient * 2 + 1
            } else {
                rest = rest + rest
                quotient = quotient * 2
            }
            if bit == 1 {
                if rest >= whole - part {
                    rest = rest - (whole - part)
                    quotient += 1
                } else {
                    rest = rest + part
                }
            }
        }
        quotient
    }
}

fn message(e: LoginError) -> String {
    match e {
        LoginError.NoSuchUser(name) => "no user {name}"
        LoginError.WrongPassword => "wrong password"
        LoginError.Locked(minutes) => "locked for {minutes} minutes"
    }
}

fn port_sum(text: String) -> Int ! PortError {
    const parts = text.split(":")
    if parts.len() != 2 {
        fail PortError.Bad(text: text)
    }
    const a = try parse_port(parts[0])
    const b = try parse_port(parts[1])
    a + b
}

fn city(u: User) -> String {
    const name = u.address?.city ?? "unknown"
    name.upper()
}

fn sum_squares(from: Int, to: Int) -> Int {
    let total = 0
    for i in from..to {
        total += i * i
    }
    total
}

fn squares(n: Int) -> Int ! Error {
    const mid = n / 2
    const first = spawn sum_squares(1, mid + 1)
    const rest = spawn sum_squares(mid + 1, n + 1)
    const a = try first.wait()
    const b = try rest.wait()
    a + b
}

fn total_qty(text: String) -> Int {
    match json.decode<[Item]>(text) {
        ok(items) => items.sum(.qty)
        err(_) => -1
    }
}

fn total(items: [(Decimal, Int)]) -> Decimal {
    let sum: Decimal = 0
    for (price, quantity) in items {
        sum += price * Decimal(quantity)
    }
    sum
}

fn deposit(a: Account, amount: Int) -> Account {
    a with { balance: a.balance + amount }
}

fn swap_ends(inout xs: [Int]) {
    if xs.len() >= 2 {
        const last = xs.len() - 1
        const first = xs[0]
        xs[0] = xs[last]
        xs[last] = first
    }
}

fn keys_at_least(m: [String: Int], min: Int) -> [String] {
    let out: [String] = []
    for (key, value) in m {
        if value >= min {
            out.push(key)
        }
    }
    out.sort()
}

fn numbered(items: [String]) -> String {
    let lines: [String] = []
    let n = 0
    for item in items {
        n += 1
        lines.push("{n}. {item}")
    }
    lines.join("\n")
}

fn add_or_none(a: Int, b: Int) -> Int?
    example add_or_none(1, 2) == 3
    example add_or_none(9223372036854775807, 1) == none
{
    const max = 9223372036854775807
    const min = -9223372036854775807 - 1
    if b > 0 and a > max - b {
        return none
    }
    if b < 0 and a < min - b {
        return none
    }
    a + b
}

fn adder(step: Int) -> fn(Int) -> Int {
    x => x + step
}

fn key_count(events: [Event]) -> Int {
    let total = 0
    for event in events {
        match event {
            Event.Key(_) => {
                total += 1
            }
            _ => {}
        }
    }
    total
}

fn csv(n: Int) -> String {
    let text = ""
    let i = 1
    while i <= n {
        if i > 1 {
            text += ","
        }
        text += "{i}"
        i += 1
    }
    text
}

fn strip_vowels(text: String) -> String
    example strip_vowels("Hello World") == "Hll Wrld"
    example strip_vowels("AEIOUaeiou") == ""
    example strip_vowels("") == ""
{
    let result = text
    for vowel in ["a", "e", "i", "o", "u", "A", "E", "I", "O", "U"] {
        result = result.replace(vowel, "")
    }
    result
}

fn is_power_of_two(n: Int) -> Bool
    example is_power_of_two(1) == true
    example is_power_of_two(8) == true
    example is_power_of_two(6) == false
    example is_power_of_two(0) == false
    example is_power_of_two(-4) == false
{
    if n <= 0 {
        return false
    }
    let value = n
    while value % 2 == 0 {
        value = value / 2
    }
    value == 1
}

fn binary(n: Int) -> String
    require n >= 0
    example binary(0) == "0"
    example binary(5) == "101"
{
    if n == 0 {
        return "0"
    }
    let out = ""
    let rest = n
    while rest > 0 {
        out = "{rest % 2}{out}"
        rest = rest / 2
    }
    out
}

fn mode(xs: [Int]) -> Int
    require xs.len() > 0
    example mode([1, 2, 2, 3]) == 2
    example mode([3, 1, 3, 1]) == 1
    example mode([7]) == 7
{
    const sorted = xs.sort()
    let best = sorted[0]
    let best_count = 0
    let current = sorted[0]
    let current_count = 0
    for x in sorted {
        if x == current {
            current_count += 1
        } else {
            current = x
            current_count = 1
        }
        if current_count > best_count {
            best = current
            best_count = current_count
        }
    }
    best
}

fn zip_map(keys: [String], values: [Int]) -> [String: Int] {
    let result: [String: Int] = [:]
    const n = if keys.len() < values.len() { keys.len() } else { values.len() }
    for i in 0..n {
        result[keys[i]] = values[i]
    }
    result
}

fn triangle(a: Int, b: Int, c: Int) -> String {
    if a <= 0 or b <= 0 or c <= 0 {
        return "invalid"
    }
    // Subtraction avoids overflow for very large sides.
    if a - b >= c or b - c >= a or c - a >= b {
        return "invalid"
    }
    if a == b and b == c {
        return "equilateral"
    }
    if a == b or b == c or a == c {
        return "isosceles"
    }
    "scalene"
}

fn lengths(text: String) -> [Int] {
    if text == "" {
        return []
    }
    text.split(" ").map(w => w.len())
}

fn collatz(n: Int) -> Int
    require n >= 1
    example collatz(1) == 0
    example collatz(6) == 8
    example collatz(27) == 111
    example collatz(1099511627775) == 534
{
    // Largest value for which 3n + 1 still fits in Int.
    const safe = 3_074_457_345_618_258_602
    let current = n
    let steps = 0
    while current != 1 and (current % 2 == 0 or current <= safe) {
        if current % 2 == 0 {
            current = current / 2
        } else {
            current = 3 * current + 1
        }
        steps += 1
    }
    if current == 1 {
        return steps
    }
    // The sequence climbs past what Int can hold: carry on with BigInt.
    let big: BigInt = BigInt(current)
    while big != 1 {
        if big % 2 == 0 {
            big = big / 2
        } else {
            big = big * 3 + 1
        }
        steps += 1
    }
    steps
}

fn sum_digits(text: String) -> Int
    example sum_digits("a1b2c3") == 6
    example sum_digits("") == 0
    example sum_digits("no digits") == 0
{
    const digits = "0123456789"
    let total = 0
    for i in 0..text.len() {
        const ch = text.slice(i, i + 1)
        for d in 0..10 {
            if digits.slice(d, d + 1) == ch {
                total += d
            }
        }
    }
    total
}

fn top(players: [Player], k: Int) -> [String] {
    if k <= 0 {
        return []
    }
    // -1 - score reverses the order without overflowing for any Int
    players.sort_by(p => -1 - p.score).take(k).map(.name)
}

fn is_sorted(xs: [Int]) -> Bool
    example is_sorted([1, 2, 2, 3]) == true
    example is_sorted([3, 1]) == false
{
    let sorted = true
    let i = 1
    while i < xs.len() {
        if xs[i - 1] > xs[i] {
            sorted = false
        }
        i += 1
    }
    sorted
}

fn hex_digit(n: Int) -> String
    require n >= 0 and n < 16
{
    const digits = "0123456789abcdef"
    digits.slice(n, n + 1)
}

fn hex_byte(n: Int) -> String
    require n >= 0 and n <= 255
{
    hex_digit(n / 16) + hex_digit(n % 16)
}

fn hex(r: Int, g: Int, b: Int) -> String
    require r >= 0 and r <= 255
    require g >= 0 and g <= 255
    require b >= 0 and b <= 255
    example hex(255, 0, 171) == "#ff00ab"
    example hex(0, 0, 0) == "#000000"
{
    "#" + hex_byte(r) + hex_byte(g) + hex_byte(b)
}

fn simulate(commands: [Int]) -> [Int] {
    let queue: [Int] = []
    let head = 0
    for c in commands {
        if c > 0 {
            queue.push(c)
        } else if c == 0 and head < queue.len() {
            head += 1
        }
    }
    queue.skip(head)
}
